import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class AuthConfigService implements OnModuleInit {
  private readonly logger = new AppLogger(AuthConfigService.name);

  public constructor(private readonly configService: ConfigService) {}

  public get secretUserName(): string {
    return this.configService.get<string>('secretUserName') ?? '';
  }

  public get secretUsernameKeyPassword(): string {
    return this.configService.get<string>('secretUsernameKeyPassword') ?? '';
  }

  public get mainSecretStore(): string {
    return this.configService.get<string>('mainSecretStore') ?? '';
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    // List of required configurations
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'secretUserName', value: this.secretUserName },
      { key: 'mainSecretStore', value: this.mainSecretStore },
      {
        key: 'secretUsernameKeyPassword',
        value: this.secretUsernameKeyPassword,
      },
    ];
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.log(`All required configurations are properly set`);
  }
}

