import {
  Controller,
  Get,
  InternalServerErrorException,
  NotFoundException,
  Param,
  ParseArrayPipe,
  Query,
  Res,
  UseFilters,
} from '@nestjs/common';
import {
  ApiInternalServerErrorResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
} from '@nestjs/swagger';
import { Response } from 'express';
import { AlertConfig } from './alert-config.entity';
import { AlertConfigByPlantAndWorkcenterDTO } from './dtos/alert-config-byplant-workcenter-parameter-dto';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';
import { AlertConfigService } from '@/modules/alert-config/alert-config.service';
// Controller for handling alert config
@Controller('alert-config')
export class AlertConfigController {
  public constructor(private readonly alertConfigService: AlertConfigService) {}

  @ApiOperation({
    description:
      'This endpoint lets you get a picking order of from a specific plant by id ',
    summary: 'Get picking order by plant and id',
  })
  @ApiOkResponse({
    description: 'The picking order ',
    type: AlertConfig,
  })
  @ApiNotFoundResponse({
    description: 'Picking Order Not Found.',
    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @Get('/:plant/:workcenter')
  public async getAlertConfigByPlantAndWorkcenter(
    @Param() query: AlertConfigByPlantAndWorkcenterDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { workcenter, plant } = query;
    try {
      const result =
        await this.alertConfigService.getAlertConfigByPlantAndWorkcenter(
          plant,
          workcenter,
        );
      return response.json(result);
    } catch (error) {
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve  alert config',
              error,
            );
      throw errorException;
    }
  }

  @Get('/:plant')
  @UseFilters(MesGenericErrorFilter)
  public async getResourceDetailsByWcIds(
    @Param('plant') plant: number,
    @Query('wcIds', new ParseArrayPipe({ items: String, separator: ',' }))
    workcenterIds: Array<string>,
    @Res() response: Response,
  ): Promise<Response> {
    const result =
      await this.alertConfigService.getAlertConfigByPlantAndWorkcenters(
        plant,
        workcenterIds,
      );
    return response.json(result);
  }
}

