import { AlertConfigResponseDto } from './dtos/alert-config-response-dto';
import { AppLogger } from '@/common/logger/app-logger';
import { AlertConfig } from '@/modules/alert-config/alert-config.entity';

@Injectable()
export class AlertConfigService {
  private readonly logger = new AppLogger(AlertConfigService.name);

  public constructor(
    @InjectRepository(AlertConfig)
    private readonly alertConfigRepo: Repository<AlertConfig>,
  ) {}

  public async getAlertConfigByPlantAndWorkcenter(
    plant: number,
    workcenter: string,
  ): Promise<AlertConfigResponseDto> {
    try {
      const responseDto = new AlertConfigResponseDto();

      const alert = await this.alertConfigRepo.findOne({
        where: [
          { plant, status: 'Activated', workcenter }, // First condition: fetch when workcenter matches
        ],
      });

      if (!alert) {
        const alertGeneral = await this.alertConfigRepo.findOne({
          where: [
            { plant, status: 'Activated', workcenter: '*' }, // Second condition: fetch when workcenter is '*'
          ],
        });
        if (alertGeneral) {
          responseDto.alertConfigId = alertGeneral.alertConfigId;
          responseDto.alertCategory = alertGeneral.alertCategory;
          responseDto.alertCode = alertGeneral.alertCode; // Manually map to DTO
          return responseDto;
        }
        throw new NotFoundException('alert config  not Found');
      }
      responseDto.alertConfigId = alert.alertConfigId;
      responseDto.alertCategory = alert.alertCategory;
      responseDto.alertCode = alert.alertCode;
      return responseDto;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve alert config by plant and workcenter : ${error.message}`,
      );
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve alert config by plant and workcenter',
              error,
            );
      throw errorException;
    }
  }

  public async getAlertConfigByPlantAndWorkcenters(
    plant: number,
    workcenters: Array<string>,
  ): Promise<Record<string, AlertConfigResponseDto>> {
    try {
      const responseMap: Record<string, AlertConfigResponseDto> = {};

      const alerts = await this.alertConfigRepo.find({
        where: [
          { plant, status: 'Activated', workcenter: In(workcenters) },
          { plant, status: 'Activated', workcenter: '*' },
        ],
      });

      if (alerts.length === 0) {
        throw new NotFoundException('No alert configs found');
      }

      for (const workcenter of workcenters) {
        const alert =
          alerts.find((a) => a.workcenter === workcenter) ||
          alerts.find((a) => a.workcenter === '*');
        if (alert) {
          responseMap[workcenter] = {
            alertCategory: alert.alertCategory,
            alertCode: alert.alertCode,
            alertConfigId: alert.alertConfigId,
          };
        }
      }

      return responseMap;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve alert configs by plant and workcenters: ${error.message}`,
      );
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve alert configs by plant and workcenters',
              error,
            );
      throw errorException;
    }
  }
}

import { ApiProperty } from '@nestjs/swagger';
import { Type } from 'class-transformer/';
import { IsNotEmpty, IsNumber, IsString, Max, Min } from 'class-validator';

export class AlertConfigByPlantAndWorkcenterDTO {
  @Type(() => Number)
  @IsNumber()
  @IsNotEmpty()
  @Min(1000)
  @Max(9999)
  @ApiProperty({
    description: 'Plant code, which must consist of exactly 4 numbers',
    example: 1146,
    required: true,
  })
  public plant: number;

  @IsNotEmpty()
  @ApiProperty({
    description: 'Workcenter maximum length is 8 ',
    example: 'WC13229',
    maxLength: 8,
    required: true,
  })
  @IsString()
  @Type(() => String)
  public workcenter: string;
}

export class AlertConfigResponseDto {
  public alertConfigId: number;

  public alertCategory: string;

  public alertCode: string;
}

