import { Column, Entity, Index, PrimaryColumn } from 'typeorm';
import { TimeStamp } from '../generics/timestamp';

@Entity('alert')
@Index('IDX_ALERT_PLANT_PICKING_ORDER_ID_CREATED_AT_DESC', [
  'plant',
  'pickingOrderId',
  'createdAt',
])
@Index('IDX_ALERT_PLANT_PICKING_ORDER_ID_UPDATED_AT', [
  'plant',
  'pickingOrderId',
  'updatedAt',
])
export class Alert extends TimeStamp {
  @PrimaryColumn({ name: 'alert_id', nullable: false })
  public alertId: number;

  @PrimaryColumn({ name: 'plant', nullable: false })
  public plant: number;

  @Column({ length: 8, name: 'workcenter', nullable: false })
  public workcenter: string;

  @Column({ length: 18, name: 'material', nullable: false })
  public material: string;

  @Column({ length: 20, name: 'alert_status', nullable: false })
  public alertStatus: string;

  @Column({ length: 10, name: 'alert_level', nullable: false })
  public alertLevel: string;

  @Column({ length: 10, name: 'alert_source', nullable: false })
  public alertSource: string;

  @Column({ length: 36, name: 'picking_order_id', nullable: false })
  public pickingOrderId: string;

  @Column({ name: 'alert_config_id', nullable: false })
  public alertConfigId: number;

  @Column({ name: 'red_bell_sms', type: 'bit', default: false })
  public redBellSms: boolean;

  @Column({ name: 'yellow_sms', type: 'bit', default: false })
  public yellowSms: boolean;

  @Column({ name: 'orange_sms', type: 'bit', default: false })
  public orangeSms: boolean;

  @Column({ name: 'red_sms', type: 'bit', default: false })
  public redSms: boolean;
}

