import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In } from 'typeorm';
import { Repository } from 'typeorm/repository/Repository';
import { PlantConfig } from '../plant-config/plant-config.entity';
import { AlertByWorkcentersDetailsResponseDto } from './dtos/alert-by-workcenters-details-response.dto';
import { AlertCountsByWorkcenterResponseDto } from './dtos/alert-counts-by-workcenter-response.dto';
import { AlertResponseDto } from './dtos/alert-response-dto';
import { AlertSmsFlagUpdateDto } from './dtos/alert-sms-flag-update.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { Alert } from '@/modules/alert/alert.entity';

@Injectable()
export class AlertService {
  private readonly logger = new AppLogger(AlertService.name);

  public constructor(
    @InjectRepository(Alert)
    private readonly alertRepo: Repository<Alert>,
    @InjectRepository(PlantConfig)
    private readonly plantConfigRepo: Repository<PlantConfig>,
  ) {}

  public async getAlertListByPlant(plant: number): Promise<Array<Alert>> {
    try {
      const alerts = await this.alertRepo.find({ where: { plant } });
      if (alerts) {
        return alerts;
      }
      throw new NotFoundException('alert   not Found');
    } catch (error) {
      this.logger.error(
        `Failed to retrieve alert  by plant : ${error.message}`,
      );
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve alert config by plant and workcenter',
              error,
            );
      throw errorException;
    }
  }

  public async getAlertById(plant: number, alertid: number): Promise<Alert> {
    try {
      const alert = await this.alertRepo.findOne({
        where: { alertId: alertid, plant },
      });
      if (alert) {
        return alert;
      }
      throw new NotFoundException('alert   not Found');
    } catch (error) {
      this.logger.error(`Failed to retrieve alert  by id : ${error.message}`);
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve alert config by plant and workcenter',
              error,
            );
      throw errorException;
    }
  }

  public async getAlertByPlantAndWkId(
    plant: number,
    wkId: string,
  ): Promise<Alert> {
    try {
      const alert = await this.alertRepo.findOne({
        where: { pickingOrderId: wkId, plant },
      });
      if (alert) {
        return alert;
      }
      throw new NotFoundException('alert   not Found');
    } catch (error) {
      this.logger.error(`Failed to retrieve alert  by id : ${error.message}`);
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve alert config by plant and workcenter',
              error,
            );
      throw errorException;
    }
  }

  public async getAlertByPlantAndWkIdAnStatusNotClosed(
    plant: number,
    wkId: string,
  ): Promise<Alert> {
    try {
      const alert = await this.alertRepo.findOne({
        where: {
          pickingOrderId: wkId,
          plant,
        },
      });

      // Ensure `alertStatus` is different from 'closed'
      if (alert && alert.alertStatus !== 'Closed') {
        return alert;
      }

      throw new NotFoundException('Alert not found');
    } catch (error) {
      this.logger.error(`Failed to retrieve alert by id: ${error.message}`);
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve alert by plant and work center',
              error,
            );
      throw errorException;
    }
  }

  public async getAlertsByPickingOrderIds(
    plant: number,
    pickingOrderIds: Array<string>,
  ): Promise<
    Array<{
      alertId: number;
      alertStatus: string;
      pickingOrderId: string;
      createdAt: Date;
    }>
  > {
    try {
      const alerts = await this.alertRepo.find({
        where: {
          pickingOrderId: In(pickingOrderIds),
          plant,
        },
      });
      return alerts.map((alert) => ({
        alertId: alert.alertId,
        alertStatus: alert.alertStatus,
        createdAt: alert.createdAt,
        pickingOrderId: alert.pickingOrderId,
      }));
