  public async updateAlertsSmsFlags(
    alertUpdates: Array<AlertSmsFlagUpdateDto>,
  ): Promise<Array<Alert>> {
    try {
      const updatedAlerts: Array<Alert> = [];
      const alertsToSave: Array<Alert> = [];

      const alertIds = alertUpdates.map(({ alertId }) => alertId);
      // Find all alerts by alertId using In operator
      const allAlerts = await this.alertRepo.findBy({
        alertId: In(alertIds),
      });

      for (const { alertId, plant, alertEscalateLevel } of alertUpdates) {
        const alert = allAlerts.find(
          (a) => a.alertId === alertId && a.plant === plant,
        );
        if (!alert) {
          throw new NotFoundException(
            `Alert not found: alertId=${alertId}, plant=${plant}`,
          );
        }
        switch (alertEscalateLevel) {
          case 'YELLOW': {
            alert.yellowSms = true;
            break;
          }
          case 'RED': {
            alert.redSms = true;
            break;
          }
          case 'ORANGE': {
            alert.orangeSms = true;
            break;
          }
          case 'RED_BELL': {
            alert.redBellSms = true;
            break;
          }
          default: {
            throw new Error(`Unknown alert level: ${alertEscalateLevel}`);
          }
        }
        alertsToSave.push(alert);
      }
      // Save all alerts in one operation
      const savedAlerts = await this.alertRepo.save(alertsToSave);
      updatedAlerts.push(...savedAlerts);
      return updatedAlerts;
    } catch (error) {
      this.logger.error(
        `Failed to batch update alert SMS flags: ${error.message}`,
      );
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          'Failed to batch update alert SMS flags',
        );
      }
      throw error;
    }
  }

