  public async getAlertCountsByWorkcenter(
    plant: number,
    workcenterIds: Array<string>,
  ): Promise<Array<AlertCountsByWorkcenterResponseDto>> {
    try {
      // Query to get alert counts grouped by workcenter and alert_level
      const results = await this.alertRepo
        .createQueryBuilder('alert')
        .select('alert.workcenter', 'workcenter')
        .addSelect('alert.alert_level', 'alertLevel')
        .addSelect('COUNT(*)', 'count')
        .where('alert.plant = :plant', { plant })
        .andWhere('alert.workcenter IN (:...workcenterIds)', { workcenterIds })
        .andWhere('alert.alert_status NOT IN (:...statuses)', {
          statuses: ['Closed', 'Deleted'],
        })
        .groupBy('alert.workcenter')
        .addGroupBy('alert.alert_level')
        .getRawMany();

      // Initialize a map with default zeros for all workcenters
      const workcenterMap = new Map<
        string,
        { grey: number; yellow: number; orange: number; red: number }
      >();

      for (const wc of workcenterIds) {
        workcenterMap.set(wc, { grey: 0, orange: 0, red: 0, yellow: 0 });
      }

      // Populate counts from query results
      for (const row of results) {
        const wc = row.workcenter;
        const level = (row.alertLevel || '').toUpperCase();
        const count = Number.parseInt(row.count, 10);

        const counts = workcenterMap.get(wc);
        if (counts) {
          switch (level) {
            case 'GREY': {
              counts.grey = count;
              break;
            }
            case 'YELLOW': {
              counts.yellow = count;
              break;
            }
            case 'ORANGE': {
              counts.orange = count;
              break;
            }
            case 'RED': {
              counts.red = count;
              break;
            }
            default: {
              // Unknown level, ignore
              break;
            }
          }
        }
      }

      // Convert map to response array
      const response: Array<AlertCountsByWorkcenterResponseDto> = [];
      for (const [workcenter, counts] of workcenterMap.entries()) {
        response.push({
          grey: counts.grey,
          orange: counts.orange,
          red: counts.red,
          workcenter,
          yellow: counts.yellow,
        });
      }

      return response;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve alert counts by workcenter: ${error.message}`,
      );
      // Return zeros for all workcenters in case of error
      return workcenterIds.map((workcenter) => ({
        grey: 0,
        orange: 0,
        red: 0,
        workcenter,
        yellow: 0,
      }));
    }
  }

  public async getAlertByWorkcentersDetails(
    plant: number,
    workcenterIds: Array<string>,
  ): Promise<Array<AlertByWorkcentersDetailsResponseDto>> {
    try {
      // Define the sorting order for alert levels
      const alertLevelOrder = new Map<string, number>([
        ['RED', 1],
        ['ORANGE', 2],
        ['YELLOW', 3],
        ['GREY', 4],
      ]);

      // Query to get detailed alert information with joins
      const results = await this.alertRepo
        .createQueryBuilder('alert')
        .leftJoin(
          'picking_order',
          'po',
          'alert.picking_order_id = po.picking_order_id AND alert.plant = po.plant',
        )
        .leftJoin(
          'rescheduler_wk_history',
          'rwh',
          `po.picking_order_id = rwh.picking_order_id 
           AND po.plant = rwh.plant 
           AND rwh.updated_at = (
             SELECT MAX(rwh2.updated_at) 
             FROM rescheduler_wk_history rwh2 
             WHERE rwh2.picking_order_id = po.picking_order_id 
             AND rwh2.plant = po.plant
           )`,
        )
        .select('alert.material', 'material')
        .addSelect('alert.picking_order_id', 'wkId')
        .addSelect('po.planned_start_date', 'startPickingTime')
        .addSelect('rwh.new_picking_time', 'newPromiseTime')
        .addSelect('po.outbound', 'od')
        .addSelect('po.end_preparation_time', 'endPreparation')
        .addSelect('po.truck_departure_time', 'truckDeparture')
        .addSelect('alert.alert_status', 'alertStatus')
        .addSelect('alert.alert_level', 'alertLevel')
        .addSelect('alert.workcenter', 'workcenter')
        .addSelect('alert.alert_id', 'alertId')
        .where('alert.plant = :plant', { plant })
        .andWhere('alert.workcenter IN (:...workcenterIds)', { workcenterIds })
        .andWhere('alert.alert_status NOT IN (:...statuses)', {
          statuses: ['Closed', 'Deleted'],
        })
        .getRawMany();
      // Sort the results based on alert level
      const sortedResults = [...results].sort(
        (
          a: AlertByWorkcentersDetailsResponseDto,
          b: AlertByWorkcentersDetailsResponseDto,
        ) => {
          const levelA = (a.alertLevel || 'GREY').toUpperCase();
          const levelB = (b.alertLevel || 'GREY').toUpperCase();
          const orderA = alertLevelOrder.get(levelA) || 999;
          const orderB = alertLevelOrder.get(levelB) || 999;
          return orderA - orderB;
        },
      );

      // Map the results to the response DTO
      return sortedResults.map((row) => ({
        alertId: row.alertId,
        alertLevel: row.alertLevel,
        alertStatus: row.alertStatus,
        endPreparation: row.endPreparation,
        material: row.material,
        newPromiseTime: row.newPromiseTime,
        od: row.od,
        startPickingTime: row.startPickingTime,
        truckDeparture: row.truckDeparture,
        wkId: row.wkId,
        workcenter: row.workcenter,
      }));
    } catch (error) {
      this.logger.error(
        `Failed to retrieve alert details by workcenter: ${error.message}`,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve alert details by workcenter',
        error,
      );
    }
  }
}

