    if ('shopOrder' in item && typeof item.shopOrder === 'string') {
      return item.shopOrder;
    }
    if ('orderId' in item && typeof item.orderId === 'string') {
      return item.orderId;
    }
    if ('pickingOrderId' in item && typeof item.pickingOrderId === 'string') {
      return item.pickingOrderId;
    }
    if (
      'productionOrderId' in item &&
      typeof item.productionOrderId === 'string'
    ) {
      return item.productionOrderId;
    }
    return '';
  }

  // Mapping Function
  private static isBuffer(item: OrderItem): item is Buffer {
    return (item as Buffer).neoIntegrationTime instanceof Date; // Specific to Buffer
  }

  private static getContainerNumber(item: OrderItem): string {
    if ('containerNumber' in item && typeof item.containerNumber === 'string') {
      return item.containerNumber;
    }
    return '';
  }

  private static getBatch(item: OrderItem): string {
    return typeof item.batch === 'string' ? item.batch : '';
  }

  private static getBatchTest(item: OrderItem): string {
    return typeof item.batchTest === 'string' ? item.batchTest : '';
  }

  private static getCustomStatus(item: OrderItem): string {
    if ('neoStatus' in item) {
      return item.neoStatus === null ? item.neoStatus : '';
    }
    if ('customStatus' in item) {
      return typeof item.customStatus === 'string' ? item.customStatus : '';
    }

    return '';
  }

  private static getQtyToBuild(item: OrderItem): string {
    if ('quantity' in item && typeof item.quantity === 'number') {
      return item.quantity.toString();
    }
    if ('qtyToBuild' in item && typeof item.qtyToBuild === 'number') {
      return item.qtyToBuild.toString();
    }
    return '';
  }

  private static getCreatedProdSo(item: OrderItem): number | string {
    if ('pikNumber' in item && typeof item.pikNumber === 'number') {
      return item.pikNumber;
    }
    return '';
  }

  private static getDestinationWc(item: OrderItem): string {
    if (
      !BufferController.isBuffer(item) &&
      typeof item.destinationWc === 'string'
    ) {
      return item.destinationWc;
    }

    return '';
  }

  private static getKanbanType(item: OrderItem): string {
    if (
      !BufferController.isBuffer(item) &&
      'kanbanType' in item &&
      typeof item.kanbanType === 'string'
    ) {
      return item.kanbanType;
    }
    return 'pickingOrderId' in item || 'orderId' in item ? 'WK' : '';
  }

  private static getMaterial(item: OrderItem): string {
    if (!BufferController.isBuffer(item) && typeof item.material === 'string') {
      return item.material;
    }
    if (typeof item.materialNumber === 'string') {
      return item.materialNumber;
    }
    return '';
  }

  private static getPickingTime(item: OrderItem): Date | string {
    const pickingTime =
      'startPickingDatetime' in item
        ? item.startPickingDatetime
        : item.plannedStartDate;
    return pickingTime instanceof Date ? pickingTime : '';
  }

  private static getPlcAssigned(item: OrderItem): unknown {
    return 'plcAssigned' in item ? item.plcAssigned : '';
  }

  private static getProductionTime(item: OrderItem): Date | string {
    // Check for 'startProductionDatetime' or fallback to 'scheduledCompDate'
    const productionTime =
      'startProductionDatetime' in item
        ? item.startProductionDatetime
        : undefined;
    if (productionTime instanceof Date) {
      return productionTime;
    }
    if (
      'scheduledCompDate' in item &&
      typeof item.scheduledCompDate === 'string'
    ) {
      return item.scheduledCompDate;
    }
    return '';
