  @Post('getShopOrderList')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({ summary: 'Get ShopOrder List' })
  @ApiBody({ type: FilterDTO })
  @ApiResponse({ status: HttpStatus.OK, type: [ShoporderResponseDTO] })
  @ApiResponse({ status: HttpStatus.BAD_REQUEST })
  public async getShopOrderList(
    @Body() filters: FilterDTO,
  ): Promise<Array<ShoporderResponseDTO> | undefined> {
    const isEmpty = (field: string | Array<string> | undefined): boolean => {
      return !field || (Array.isArray(field) && field.length === 0);
    };
    const transformBoolean = (
      field: boolean | number | undefined,
    ): boolean | undefined => {
      // Explicitly convert 1 and 0 to true and false
      if (field === 1 || field === true) return true;
      if (field === 0 || field === false) return false;
      return undefined;
    };
    const splitToArray = (
      field: string | Array<string> | undefined,
    ): Array<string> | undefined => {
      if (isEmpty(field)) {
        return undefined;
      }

      if (typeof field === 'string') {
        return field.split(';');
      }
      return field;
    };
    // Create a modified copy of the filters object
    const modifiedFilters = {
      ...filters,
      KanbanType: splitToArray(filters.KanbanType) ?? [],
      CustomStatus: splitToArray(filters.CustomStatus),
      DESTINATION_WC: splitToArray(filters.DESTINATION_WC),
      FromStorageBin: splitToArray(filters.FromStorageBin),
      FromStorageLoc: splitToArray(filters.FromStorageLoc),
      Material: splitToArray(filters.Material),
      ShopOrder: splitToArray(filters.ShopOrder),
      Status: splitToArray(filters.Status),
      TPA: splitToArray(filters.TPA),
      ToStorageBin: splitToArray(filters.ToStorageBin),
      ToStorageLoc: splitToArray(filters.ToStorageLoc),
      WorkCenter: splitToArray(filters.WorkCenter),
      Customer: filters.Customer?.trim() ?? undefined,
      EndPickingTime: filters.EndPickingTime?.trim() ?? undefined,
      EndProductionTime: filters.EndProductionTime?.trim() ?? undefined,
      StartPickingTime: filters.StartPickingTime?.trim() ?? undefined,
      StartProductionTime: filters.StartProductionTime?.trim() ?? undefined,
      AGVAssigned: transformBoolean(filters.AGVAssigned),
      OnlyPastPickingTime: transformBoolean(filters.OnlyPastPickingTime),
      PLCAssigned: transformBoolean(filters.PLCAssigned),
      WMS_ASSIGNED: transformBoolean(filters.WMS_ASSIGNED),
    };
    if (!modifiedFilters.KanbanType) return [];

    const isKanbanTypePIKorGHOSTorRW = ['PIK', 'GHOST', 'RW'].some((type) =>
      modifiedFilters.KanbanType?.includes(type),
    );
    const isKanbanTypeWK = modifiedFilters.KanbanType?.includes('WK');

    const fetchPromises = [
      ...(isKanbanTypeWK && modifiedFilters.CustomStatus?.includes('OPEN')
        ? [this.bufferSer.getFilteredBufferData(modifiedFilters)]
        : [Promise.resolve([])]),
      ...(isKanbanTypeWK
        ? [this.pickingOrderSer.getFilteredPickingData(modifiedFilters)]
        : []),
      ...(isKanbanTypePIKorGHOSTorRW
        ? [this.productionOrderSer.getFilteredProductionData(modifiedFilters)]
        : []),
    ];

    const [bufferData, pickingOrderData, productionOrderData] =
      await Promise.all(fetchPromises);

    const combinedData = [
      ...(Array.isArray(pickingOrderData) ? pickingOrderData : []),
      ...(Array.isArray(bufferData) ? bufferData : []),
      ...(Array.isArray(productionOrderData) ? productionOrderData : []),
    ];

    // Remove duplicates, keeping the first occurrence, which will be from pickingOrderData if a duplicate exists
    const uniqueData = uniqBy(combinedData, (item: OrderItem) =>
      BufferController.getShopOrder(item),
    );
    const mappedData = uniqueData.map(BufferController.mapToShoporderResponse);
    return mappedData;
  }

