  @Post('process-orders')
  @ApiOperation({
    description:
      'This endpoint processes orders from an XML input, fetching statuses for the given order IDs and returning the result in XML format.',
    summary: 'Process orders from XML input',
  })
  @ApiBody({
    description: 'XML input containing Plant and Order IDs.',
    required: true,
    schema: {
      example: `<Root>
    <GeneralWKData>
      <Plant>PLANT_CODE</Plant>
    </GeneralWKData>
    <WithdrawalKanban>
      <OrderID>ORDER_ID_1</OrderID>
      <OrderID>ORDER_ID_2</OrderID>
    </WithdrawalKanban>
  </Root>`,
      type: 'string',
    },
  })
  @ApiResponse({
    content: {
      applicationXml: {
        example: `<Rowsets>
    <Rowset>
      <Row>
        <Result>SUCCESS</Result>
        <ErrorLog></ErrorLog>
        <OrderID>ORDER_ID_1</OrderID>
        <Plant>PLANT_CODE</Plant>
        <Status>Active</Status>
      </Row>
      <Row>
        <Result>FAILURE</Result>
        <ErrorLog>ORDER_ID_2 does not exist</ErrorLog>
        <OrderID>ORDER_ID_2</OrderID>
        <Plant>PLANT_CODE</Plant>
        <Status></Status>
      </Row>
    </Rowset>
  </Rowsets>`,
      },
    },
    description: 'The processed orders result in XML format.',
    status: 200,
  })
  @ApiResponse({
    description: 'Invalid input XML: Missing Plant or OrderID data.',
    status: 400,
  })
  public async processOrders(@Body() body: string): Promise<string> {
    // Parse input XML
    const options = {
      ignoreAttributes: false, // Keep attributes intact
      parseAttributeValue: false, // Prevent parsing attribute values into numbers/booleans
      parseNodeValue: false, // Prevent parsing node values into numbers/booleans
    };
    const xmlParser = new XMLParser(options);
    const parsedInput = xmlParser.parse(body);

    const plant = parsedInput?.Root?.GeneralWKData?.Plant;
    const orderIds = parsedInput?.Root?.WithdrawalKanban?.OrderID;

    // Ensure orderIds is an array
    const orderIdArray = Array.isArray(orderIds) ? orderIds : [orderIds];

    if (!plant || orderIdArray.length === 0) {
      throw new Error('Invalid input XML: Missing Plant or OrderID data.');
    }

    const results = await Promise.all(
      orderIdArray.map((orderId: string) =>
        this.bufferSer.getOrderStatus(orderId, plant),
      ),
    );

    // Map results into the desired RowDto format
    const rows = results.map(
      (result) =>
        new RowDto(
          result.status === undefined ? 'FAILURE' : 'SUCCESS',
          result.status === undefined ? `${result.orderId} does not exist` : '',
          result.orderId,
          result.plant,
          result.status ?? null,
        ),
    );

    const rowsetDto = new RowsetDto(rows);
    const rowsetsDto = new RowsetsDto(rowsetDto);

    // Convert the output object to XML
    const builderOptions = { format: true, ignoreAttributes: false };
    const xmlBuilder = new XMLBuilder(builderOptions);
    const xmlOutput = xmlBuilder.build(rowsetsDto);

    return xmlOutput;
  }

