  @Get('latest/:orderId')
  @ApiOperation({ summary: 'Get the latest buffer entry for an orderId' })
  @ApiParam({
    description: 'The order ID to fetch the latest buffer entry for',
    name: 'orderId',
    required: true,
    schema: { type: 'string' },
  })
  @ApiResponse({
    description: 'Successfully retrieved latest buffer entry',
    status: HttpStatus.OK,
    type: Buffer,
  })
  @ApiResponse({
    description: 'No buffer entry found for the specified orderId',
    status: HttpStatus.NOT_FOUND,
  })
  public async getLatestBufferByOrderId(
    @Param('orderId') orderId: string,
  ): Promise<Buffer | { error: string }> {
    const result = await this.bufferSer.findLatestByOrderId(orderId);
    if (!result) {
      return { error: `No buffer entry found for orderId: ${orderId}` };
    }
    return result;
  }

  /**
   * Get the latest buffer entries for a list of orderIds
   * POST /buffer/latest/bulk
   * @param body The request body containing the list of orderIds
   * @returns An array of the latest buffer entries corresponding to the provided orderIds
   */
  @Post('latest/bulk')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Get the latest buffer entries for a list of orderIds',
  })
  @ApiBody({ type: GetLatestBufferDto })
  @ApiResponse({
    description: 'Successfully retrieved latest buffer entries',
    status: HttpStatus.OK,
    type: [Buffer],
  })
  public async getLatestBufferByOrderIds(
    @Body() body: GetLatestBufferDto,
  ): Promise<Array<Buffer>> {
    return this.bufferSer.findLatestByOrderIds(body.orderIds);
  }

  /**
   * Reset buffer entry statuses to go through the normal WK integration flow again
   * PUT /buffer/:id/reprocess-status
   * @param id The ID of the buffer entry to reset
   * @param dto The buffer entity containing updated fields for reprocessing
   * @returns buffer
   */
  @Put(':id/reprocess-status')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary:
      'Reset buffer entry statuses (bufferStatus=RECEIVED, neoStatus=null, errorLog=null, neoIntegrationTime=null) to re-enter the WK integration flow',
  })
  @ApiParam({
    description: 'The buffer entry ID to reset',
    name: 'id',
    required: true,
    schema: { type: 'integer' },
  })
  @ApiResponse({
    description: 'Successfully reset buffer entry for reprocess',
    status: HttpStatus.OK,
    type: Buffer,
  })
  public async resetBufferForReprocess(
    @Param('id', ParseIntPipe) id: number,
    @Body() dto: CreateBufferTableDto,
  ): Promise<Buffer | { error: string }> {
    try {
      const buffer = await this.bufferSer.resetBufferForReprocess(id, dto);
      return buffer;
    } catch (error) {
      return { error: error.message };
    }
  }
}

