  public async getBufferDataByCriteria(
    plant: string,
    criteria: {
      actionTypeList: Array<string>;
      bufferStatusList: Array<string>;
      shopOrderList: Array<string>;
      neostatusList: Array<string>;
      customerList: Array<string>;
      materialList: Array<string>;
      sourceLocationList: Array<string>;
      destinationLocationList: Array<string>;
      outboundDeliveryList: Array<string>;
      workcenterList: Array<string>;
      startDate: Date;
      endDate: Date;
      page: number;
      pageSize: number;
    },
  ): Promise<PaginatedBufferResponseDto> {
    const safePage =
      Number.isInteger(criteria.page) && criteria.page > 0 ? criteria.page : 1;
    const requestedPageSize =
      Number.isInteger(criteria.pageSize) && criteria.pageSize > 0
        ? criteria.pageSize
        : this.defaultPageSize;
    const pageSize = Math.min(requestedPageSize, this.maxPageSize);
    const skip = (safePage - 1) * pageSize;

    const queryBuilder = this.bufferRepository
      .createQueryBuilder('buffer')
      .where('buffer.plant = :plant', { plant });

    if (criteria.startDate) {
      queryBuilder.andWhere('buffer.createdAt >= :startDate', {
        startDate: criteria.startDate,
      });
    }

    if (criteria.endDate) {
      queryBuilder.andWhere('buffer.createdAt <= :endDate', {
        endDate: criteria.endDate,
      });
    }
    if (criteria.shopOrderList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.orderId IN (:...shopOrderList)', {
        shopOrderList: criteria.shopOrderList.filter(Boolean),
      });
    }
    if (criteria.actionTypeList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.actionType IN (:...actionTypeList)', {
        actionTypeList: criteria.actionTypeList.filter(Boolean),
      });
    }

    if (
      Array.isArray(criteria.neostatusList) &&
      (criteria.neostatusList.some(
        (status) => status !== 'null' && Boolean(status),
      ) ||
        criteria.neostatusList.includes('null'))
    ) {
      queryBuilder.andWhere(
        new Brackets((qb) => {
          // Add conditions for non-null statuses
          const nonNullStatuses = criteria.neostatusList.filter(
            (status) => status !== 'null' && Boolean(status),
          );
          if (nonNullStatuses.length > 0) {
            qb.where('buffer.neoStatus IN (:...nonNullStatuses)', {
              nonNullStatuses,
            });
          }

          // Add condition for NULL statuses
          if (criteria.neostatusList.includes('null')) {
            qb.orWhere('buffer.neoStatus IS NULL');
          }
        }),
      );
    }

    if (criteria.bufferStatusList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.bufferStatus IN (:...bufferStatusList)', {
        bufferStatusList: criteria.bufferStatusList.filter(Boolean),
      });
    }

    if (criteria.customerList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.customer IN (:...customerList)', {
        customerList: criteria.customerList.filter(Boolean),
      });
    }

    if (criteria.materialList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.materialNumber IN (:...materialList)', {
        materialList: criteria.materialList.filter(Boolean),
      });
    }

    if (criteria.sourceLocationList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere(
        'buffer.sourceLocation IN (:...sourceLocationList)',
        {
          sourceLocationList: criteria.sourceLocationList.filter(Boolean),
        },
      );
    }

    if (criteria.destinationLocationList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere(
        'buffer.destinationLocation IN (:...destinationLocationList)',
        {
          destinationLocationList:
            criteria.destinationLocationList.filter(Boolean),
        },
      );
    }

    if (criteria.outboundDeliveryList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere(
        'buffer.deliveryNumber IN (:...outboundDeliveryList)',
        {
          outboundDeliveryList: criteria.outboundDeliveryList.filter(Boolean),
        },
      );
    }

    if (criteria.workcenterList?.filter(Boolean).length > 0) {
      queryBuilder.andWhere('buffer.productionLine IN (:...workcenterList)', {
        workcenterList: criteria.workcenterList.filter(Boolean),
      });
    }

    queryBuilder.orderBy('buffer.createdAt', 'DESC').skip(skip).take(pageSize);

    const [data, total] = await queryBuilder.getManyAndCount();

    return {
      data,
      page: safePage,
      pageSize,
      total,
    };
  }

  public async getOrderStatus(
    orderId: string,
    plant: number,
  ): Promise<{
    orderId: string;
    plant: number;
    status: string | undefined;
    errorLog: string | null;
  }> {
    try {
      const pickingOrderResult = await this.pickingRepository.findOne({
        where: { pickingOrderId: orderId, plant },
      });

      let status: string | undefined;
      if (pickingOrderResult) {
        status = pickingOrderResult.customStatus;
      } else {
        const bufferResult = await this.bufferRepository.findOne({
          order: { updatedAt: 'DESC' },
          where: { orderId, plant },
        });
        status = bufferResult?.neoStatus ?? bufferResult?.bufferStatus;
      }

      return {
        errorLog: null,
        orderId,
        plant,
        status: status || undefined,
      };
    } catch (error) {
      throw new Error(
        `Error fetching status for orderId: ${orderId}, plant: ${plant}. Details: ${error.message}`,
      );
    }
  }

  public async getOrderStatusBatch(
    orderIds: Array<string>,
    plant: number,
  ): Promise<
    Array<{
      orderId: string;
      plant: number;
      status: string | undefined;
      errorLog: string | null;
    }>
  > {
    try {
      const batchSize = 500;
      const batches: Array<Array<string>> = [];

      // Split orderIds into batches of 500
      for (let index = 0; index < orderIds.length; index += batchSize) {
        batches.push(orderIds.slice(index, index + batchSize));
      }

      // Process all batches in parallel
      const batchResults = await Promise.all(
        batches.map(async (batch) => {
          // Fetch picking orders for the batch
          const pickingOrders = await this.pickingRepository
            .createQueryBuilder('picking')
            .select([
              'picking.pickingOrderId',
              'picking.customStatus',
              'picking.updatedAt',
            ])
            .where('picking.pickingOrderId IN (:...orderIds)', {
              orderIds: batch,
            })
            .andWhere('picking.plant = :plant', { plant })
            .getMany();

          // Create a map of picking orders
          const pickingOrderMap = new Map(
            pickingOrders.map((po) => [po.pickingOrderId, po]),
          );

          // Find orderIds not in picking orders
          const orderIdsNotInPicking = batch.filter(
            (id) => !pickingOrderMap.has(id),
          );

          // Fetch buffer entries for orderIds not found in picking
          let bufferEntries: Array<Buffer> = [];
          if (orderIdsNotInPicking.length > 0) {
            // Subquery to get the latest buffer entry for each orderId
            const latestBufferSubQuery = this.bufferRepository
              .createQueryBuilder('subBuffer')
              .select('subBuffer.orderId', 'orderId')
              .addSelect('MAX(subBuffer.updatedAt)', 'maxUpdatedAt')
              .where('subBuffer.orderId IN (:...orderIds)', {
                orderIds: orderIdsNotInPicking,
              })
              .andWhere('subBuffer.plant = :plant', { plant })
              .groupBy('subBuffer.orderId');

            bufferEntries = await this.bufferRepository
              .createQueryBuilder('buffer')
              .innerJoin(
                `(${latestBufferSubQuery.getQuery()})`,
                'latestBuffer',
                'buffer.orderId = latestBuffer.orderId AND buffer.updatedAt = latestBuffer.maxUpdatedAt',
              )
              .select([
                'buffer.orderId',
                'buffer.neoStatus',
                'buffer.bufferStatus',
                'buffer.updatedAt',
              ])
              .where('buffer.orderId IN (:...orderIds)', {
                orderIds: orderIdsNotInPicking,
              })
              .andWhere('buffer.plant = :plant', { plant })
              .setParameters(latestBufferSubQuery.getParameters())
              .getMany();
          }

          // Create a map of buffer entries
          const bufferMap = new Map(
            bufferEntries.map((buffer) => [buffer.orderId, buffer]),
          );

          // Build results for this batch
          return batch.map((orderId) => {
            let status: string | undefined;

            const pickingOrder = pickingOrderMap.get(orderId);
            if (pickingOrder) {
              status = pickingOrder.customStatus;
            } else {
              const buffer = bufferMap.get(orderId);
              status = buffer?.neoStatus ?? buffer?.bufferStatus;
            }

            return {
              errorLog: null,
              orderId,
              plant,
              status: status || undefined,
            };
          });
        }),
      );

      // Flatten the results from all batches
      return batchResults.flat();
    } catch (error) {
      throw new Error(
        `Error fetching status for orderIds in batch, plant: ${plant}. Details: ${error.message}`,
      );
    }
  }

  public async getRecentBufferWksByPlant(
    plant: number,
    updatedSince: Date,
  ): Promise<Array<BufferWkResponseDto>> {
    try {
      return await this.bufferRepository.query(
        `
    WITH ranked_buffer AS (
      SELECT 
        order_id AS "shopOrder",
        plant,
        created_at AS "createdAt",
        updated_at AS "updatedAt",
        buffer_status AS "bufferStatus",
        neo_status AS "neoStatus",
        production_line AS "wcCode",
        tpa_number AS "tpaNumber",
        source_location AS "sourceLocation",
        destination_location AS "destinationLocation",
        delivery_number AS "outbound",
        quantity AS "qtyToBuild",
        batch AS "batch",
        material_number AS "material",
        start_picking_date_time AS "plannedStartDate",
        customer AS "customer",
        ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY updated_at DESC) AS rn
      FROM buffer
      WHERE plant = @0
        AND (buffer_status IN ('RECEIVED', 'IN_PROGRESS')  OR (neo_status='ERROR'))
        AND updated_at > @1
        AND action_type != 'Deletion'
    )
        SELECT
    shopOrder,
    createdAt,
    updatedAt,
    bufferStatus,
    neoStatus,
      plant,
      wcCode,
      tpaNumber,
      sourceLocation,
      destinationLocation,
      outbound,
      qtyToBuild,
      batch,
      material,
      plannedStartDate,
      customer
    FROM ranked_buffer
    WHERE rn = 1
    `,
        [plant, updatedSince],
      );
    } catch (error) {
      this.logger.error('Failed to fetch wks from buffer table', error);
      throw new Error(
        `Failed to retrieve recent buffer work centers : ${error.message}`,
      );
    }
  }

  public async getRecentBufferWksByPlantPaginated(
    plant: number,
    limit: number,
    offset: number,
  ): Promise<Array<BufferWkResponseDto>> {
    try {
      const query = `
        WITH ranked_buffer AS (
          SELECT 
            order_id AS "shopOrder",
            plant,
            created_at AS "createdAt",
            updated_at AS "updatedAt",
            buffer_status AS "bufferStatus",
            production_line AS "wcCode",
            tpa_number AS "tpaNumber",
            source_location AS "sourceLocation",
            destination_location AS "destinationLocation",
            delivery_number AS "outbound",
            quantity AS "qtyToBuild",
            material_number AS "material",
            start_picking_date_time AS "plannedStartDate",
            customer AS "customer",
            ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY updated_at DESC) AS rn
          FROM buffer
          WHERE plant = @0
            AND buffer_status IN ('RECEIVED', 'IN_PROGRESS')
        )
        SELECT
          shopOrder,
          createdAt,
          updatedAt,
          bufferStatus,
          plant,
          wcCode,
          tpaNumber,
          sourceLocation,
          destinationLocation,
          outbound,
          qtyToBuild,
          material,
          plannedStartDate,
          customer
        FROM ranked_buffer
        WHERE rn = 1
        ORDER BY updatedAt DESC
        OFFSET @1 ROWS FETCH NEXT @2 ROWS ONLY;
      `;
      const result = await this.bufferRepository.query(query, [
        plant,
        offset,
        limit,
      ]);

      return result;
    } catch (error) {
      this.logger.error('Failed to fetch wks from buffer table', error);
      throw new Error(
        `Failed to retrieve recent buffer work centers : ${error.message}`,
      );
    }
  }

  /**
   * Find the latest buffer entry for a given orderId (most recent updatedAt)
   * @param orderId id order
   * @returns a buffer or null
   */
  public async findLatestByOrderId(orderId: string): Promise<Buffer | null> {
    return this.bufferRepository.findOne({
      where: { orderId },
      order: { updatedAt: 'DESC' },
    });
  }

  /**
   * Find the latest buffer entries for a list of orderIds (most recent updatedAt per orderId)
   * @param orderIds list of orders
   * @returns array of buffer
   */
  public async findLatestByOrderIds(
    orderIds: Array<string>,
  ): Promise<Array<Buffer>> {
    if (!orderIds || orderIds.length === 0) {
      return [];
    }

    const subQuery = this.bufferRepository
      .createQueryBuilder('subBuffer')
      .select('subBuffer.orderId', 'orderId')
      .addSelect('MAX(subBuffer.updatedAt)', 'maxUpdatedAt')
      .where('subBuffer.orderId IN (:...orderIds)', { orderIds })
      .groupBy('subBuffer.orderId');

    const results = await this.bufferRepository
      .createQueryBuilder('buffer')
      .innerJoin(
        `(${subQuery.getQuery()})`,
        'latestBuffer',
        'buffer.orderId = latestBuffer.orderId AND buffer.updatedAt = latestBuffer.maxUpdatedAt',
      )
      .where('buffer.orderId IN (:...orderIds)', { orderIds })
      .setParameters(subQuery.getParameters())
      .getMany();

    return results;
  }

  /**
   * Reset the buffer entry statuses so it goes through the normal WK integration flow again.
   * Resets bufferStatus to 'RECEIVED', neoStatus to null, errorLog to null, neoIntegrationTime to null.
   * @param id id of buffer
   * @param dto buffer data transfer object
   * @returns A promise that resolves to the updated Buffer entity.
   */
  public async resetBufferForReprocess(
    id: number,
    dto: CreateBufferTableDto,
  ): Promise<Buffer> {
    const buffer = await this.bufferRepository.findOne({ where: { id } });

    if (!buffer) {
      throw new Error(`Buffer entry with id ${id} not found`);
    }

    buffer.bufferStatus = dto.bufferStatus;
    buffer.neoStatus = dto.neoStatus;
    buffer.errorLog = dto.errorLog;
    buffer.neoIntegrationTime = dto.neoIntegrationTime;

    return this.bufferRepository.save(buffer);
  }
}

