import {
  Body,
  Controller,
  HttpStatus,
  Post,
  Res,
  UseFilters,
} from '@nestjs/common';
import {
  ApiOperation,
  ApiOkResponse,
  ApiInternalServerErrorResponse,
  ApiBody,
  ApiTags,
} from '@nestjs/swagger';
import { Response } from 'express';
import { CleanupOrchestrationService } from './cleanup-orchestration.service';
import { CleanupOrchestrationOptionsDto } from './dtos/cleanup-orchestration-options.dto';
import { CleanupOrchestrationResponseDto } from './dtos/cleanup-orchestration-response.dto';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';

@ApiTags('Cleanup Orchestration')
@Controller('cleanup-orchestration')
export class CleanupOrchestrationController {
  public constructor(
    private readonly cleanupOrchestrationService: CleanupOrchestrationService,
  ) {}

  @Post('/run-all-cleanups-parallel')
  @UseFilters(MesGenericErrorFilter)
  @ApiOperation({
    summary: 'Run all cleanup procedures in parallel for all plants',
    description: `
      Executes all cleanup procedures (Alert, Buffer, Picking Order, and Production Order) 
      in parallel for all plants in the plant_config table.

      This endpoint orchestrates:
      - Alert cleanup (usp_cleanup_alert_closed_deleted)
      - Buffer cleanup (deleteExpiredOrders - removes orders older than 10 days)
      - Picking Order cleanup (ProcedureCleansing)
      - Production Order cleanup (ProcedureCleansingProductionOrder)

      All four procedures run simultaneously to optimize execution time.
      The response includes individual results for each procedure and overall success status.
    `,
  })
  @ApiBody({
    description:
      'Cleanup options that will be applied to all cleanup procedures',
    type: CleanupOrchestrationOptionsDto,
    examples: {
      minimal: {
        summary: 'Minimal example with default values',
        description:
          'Uses default values for all cleanup procedures. Services will use their own defaults.',
        value: {},
      },
      standard: {
        summary: 'Standard cleanup configuration',
        description:
          'Recommended settings for regular cleanup operations with moderate load',
        value: {
          batchSize: 1000,
          delayBetweenBatch: 100,
          months: 6,
          nbRowsToClean: 10_000,
        },
      },
      aggressive: {
        summary: 'Aggressive cleanup configuration',
        description:
          'Higher throughput for major cleanup operations during low-traffic periods',
        value: {
          batchSize: 5000,
          delayBetweenBatch: 50,
          months: 12,
          nbRowsToClean: 50_000,
        },
      },
      conservative: {
        summary: 'Conservative cleanup configuration',
        description:
          'Gentle cleanup with minimal impact on database performance',
        value: {
          batchSize: 500,
          delayBetweenBatch: 500,
          months: 3,
          nbRowsToClean: 5000,
        },
      },
    },
  })
  @ApiOkResponse({
    description:
      'All cleanup procedures executed (check individual results for success/failure)',
    type: CleanupOrchestrationResponseDto,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  public async runAllCleanupProceduresInParallel(
    @Body() options: CleanupOrchestrationOptionsDto,
    @Res() response: Response,
  ): Promise<Response> {
    const result =
      await this.cleanupOrchestrationService.runAllCleanupProceduresInParallel(
        options,
      );

    // Return 200 even if some procedures failed, but include detailed results
    // This allows the client to see which specific procedures succeeded/failed
    return response.status(HttpStatus.OK).json(result);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PickingOrderJobOptionsDto } from '../picking-order/dtos/picking-order-job-options.dto';
import { CleanupLog } from './cleanup-log.entity';
import { CleanupOrchestrationOptionsDto } from './dtos/cleanup-orchestration-options.dto';
import { CleanupOrchestrationResponseDto } from './dtos/cleanup-orchestration-response.dto';
import { CleanupOrchestrationResultDto } from './dtos/cleanup-orchestration-result.dto';
import { BufferService } from '@/modules/buffer/buffer.service';
import { PickingOrderCleanupService } from '@/modules/picking-order/picking-order-cleanup.service';
import { ProductionOrderService } from '@/modules/production-order/production-order.service';

@Injectable()
export class CleanupOrchestrationService {
  private readonly logger = new Logger(CleanupOrchestrationService.name);

  public constructor(
    @InjectRepository(CleanupLog)
    private readonly cleanupLogRepo: Repository<CleanupLog>,
    private readonly bufferService: BufferService,
    private readonly pickingOrderCleanupService: PickingOrderCleanupService,
    private readonly productionOrderService: ProductionOrderService,
  ) {}

  /**
   * Orchestrates all cleanup procedures to run in parallel for all plants
   * @param options - Cleanup options to pass to all procedures
   * @returns CleanupOrchestrationResponseDto with results from all procedures
   */
  public async runAllCleanupProceduresInParallel(
    options: CleanupOrchestrationOptionsDto,
  ): Promise<CleanupOrchestrationResponseDto> {
    const startedAt = new Date();
    const startTime = Date.now();

    this.logger.log(
      'Starting parallel execution of all cleanup procedures for all plants',
    );

    // Convert orchestration options to specific service options
    const pickingOrderOptions: PickingOrderJobOptionsDto = {
      batchSize: options.batchSize,
      delayMSBetweenRuns: options.delayBetweenBatch,
      months: options.months,
      nbRowsToClean: options.nbRowsToClean,
    };

    // Run all cleanup procedures in parallel
    const results = await Promise.allSettled([
      this.runBufferCleanup(),
      this.runPickingOrderCleanup(pickingOrderOptions),
      this.runProductionOrderCleanup(pickingOrderOptions),
    ]);

    const completedAt = new Date();
    const totalDurationMs = Date.now() - startTime;

    // Process results
    const cleanupResults: Array<CleanupOrchestrationResultDto> = results.map(
      (result, index) => {
        const procedureNames = [
          'Buffer Cleanup',
          'Picking Order Cleanup',
          'Production Order Cleanup',
        ];

        if (result.status === 'fulfilled') {
          return result.value;
        }
        this.logger.error(`${procedureNames[index]} failed: ${result.reason}`);
        return {
          durationMs: 0,
          error: result.reason?.message || 'Unknown error',
          procedureName: procedureNames[index],
          success: false,
        };
      },
    );

    const overallSuccess = cleanupResults.every((result) => result.success);

    // Log the orchestration result
    await this.logOrchestrationResult(
      overallSuccess,
      totalDurationMs,
      cleanupResults,
    );

    this.logger.log(
      `All cleanup procedures completed. Overall success: ${overallSuccess}. Total duration: ${totalDurationMs}ms`,
    );

    return {
      completedAt,
      overallSuccess,
      results: cleanupResults,
      startedAt,
      totalDurationMs,
    };
  }

  /**
   * Runs buffer cleanup (deletes expired orders) and returns a result object
   * @returns CleanupOrchestrationResultDto with result information
   */
  private async runBufferCleanup(): Promise<CleanupOrchestrationResultDto> {
    const startTime = Date.now();
    try {
      this.logger.log('Starting Buffer cleanup (deleting expired orders)');
      const result = await this.bufferService.deleteExpiredOrders();
      const durationMs = Date.now() - startTime;

      await this.logCleanupProcedure(
        'Buffer Cleanup',
        'INFO',
        `Success - Deleted ${result.deletedCount} expired orders`,
        0,
      );

      return {
        durationMs,
        procedureName: 'Buffer Cleanup',
        success: true,
      };
    } catch (error) {
      const durationMs = Date.now() - startTime;
      const errorMessage = error?.message || 'Unknown error';

      await this.logCleanupProcedure(
        'Buffer Cleanup',
        'ERROR',
        `Failed: ${errorMessage}`,
        0,
      );

      return {
        durationMs,
        error: errorMessage,
        procedureName: 'Buffer Cleanup',
        success: false,
      };
    }
  }

  /**
   * Runs picking order cleanup for all plants and returns a result object
   * @param options - Picking order cleanup options
   * @returns CleanupOrchestrationResultDto with result information
   */
  private async runPickingOrderCleanup(
    options: PickingOrderJobOptionsDto,
  ): Promise<CleanupOrchestrationResultDto> {
    const startTime = Date.now();
    try {
      this.logger.log('Starting Picking Order cleanup for all plants');
      await this.pickingOrderCleanupService.runDeletePickingOrderProcedureForAllPlants(
        options,
      );
      const durationMs = Date.now() - startTime;

      await this.logCleanupProcedure(
        'Picking Order Cleanup',
        'INFO',
        'Success',
        0,
      );

      return {
        durationMs,
        procedureName: 'Picking Order Cleanup',
        success: true,
      };
    } catch (error) {
      const durationMs = Date.now() - startTime;
      const errorMessage = error?.message || 'Unknown error';

      await this.logCleanupProcedure(
        'Picking Order Cleanup',
        'ERROR',
        `Failed: ${errorMessage}`,
        0,
      );

      return {
        durationMs,
        error: errorMessage,
        procedureName: 'Picking Order Cleanup',
        success: false,
      };
    }
  }

  /**
   * Runs production order cleanup for all plants and returns a result object
   * @param options - Production order cleanup options
   * @returns CleanupOrchestrationResultDto with result information
   */
  private async runProductionOrderCleanup(
    options: PickingOrderJobOptionsDto,
  ): Promise<CleanupOrchestrationResultDto> {
    const startTime = Date.now();
    try {
      this.logger.log('Starting Production Order cleanup for all plants');
      await this.productionOrderService.runDeleteProductionOrderProcedureForAllPlants(
        options,
      );
      const durationMs = Date.now() - startTime;

      await this.logCleanupProcedure(
        'Production Order Cleanup',
        'INFO',
        'Success',
        0,
      );

      return {
        durationMs,
        procedureName: 'Production Order Cleanup',
        success: true,
      };
    } catch (error) {
      const durationMs = Date.now() - startTime;
      const errorMessage = error?.message || 'Unknown error';

      await this.logCleanupProcedure(
        'Production Order Cleanup',
        'ERROR',
        `Failed: ${errorMessage}`,
        0,
      );

      return {
        durationMs,
        error: errorMessage,
        procedureName: 'Production Order Cleanup',
        success: false,
      };
    }
  }

  /**
   * Logs cleanup procedure execution to the cleanup_logs table
   * @param processName - Name of the cleanup process
   * @param logType - Type of log entry (INFO, ERROR, or WARNING)
   * @param message - Log message
   * @param plantCode - Plant code (use 0 for all plants)
   */
  private async logCleanupProcedure(
    processName: string,
    logType: 'INFO' | 'ERROR' | 'WARNING',
    message: string,
    plantCode: number,
  ): Promise<void> {
    try {
      const log = this.cleanupLogRepo.create({
        plantCode,
        processName,
        logType,
        message,
      });
      await this.cleanupLogRepo.save(log);
    } catch (error) {
      this.logger.error(
        `Failed to log cleanup procedure: ${error?.message}`,
        error?.stack,
      );
    }
  }

  /**
   * Logs the overall orchestration result
   * @param overallSuccess - Whether all cleanup procedures succeeded
   * @param totalDurationMs - Total duration in milliseconds
   * @param results - Array of individual cleanup results
   */
  private async logOrchestrationResult(
    overallSuccess: boolean,
    totalDurationMs: number,
    results: Array<CleanupOrchestrationResultDto>,
  ): Promise<void> {
    const message = `Orchestration completed. Success: ${overallSuccess}. Duration: ${totalDurationMs}ms. Results: ${JSON.stringify(results)}`;
    await this.logCleanupProcedure(
      'Cleanup Orchestration',
      overallSuccess ? 'INFO' : 'ERROR',
      message,
      0,
    );
  }
}

