   */
  @Put('bulk')
  @HttpCode(HttpStatus.OK)
  public async updateBulk(
    @Body() updateDtos: Array<UpdateLogBufferHistoryDto>,
  ): Promise<Array<LogBufferHistory>> {
    return this.logBufferHistoryService.updateBulk(updateDtos);
  }

  /**
   * Get all log buffer history records
   * GET /log-buffer-history
   * @returns Array of LogBufferHistory records
   */
  @Get()
  public async findAll(): Promise<Array<LogBufferHistory>> {
    return this.logBufferHistoryService.findAll();
  }

  /**
   * Get a single log buffer history record by id
   * GET /log-buffer-history/:id
   * @param id - LogBufferHistory record id
   * @returns LogBufferHistory record
   */
  @Get(':id')
  public async findOne(
    @Param('id', ParseIntPipe) id: number,
  ): Promise<LogBufferHistory> {
    return this.logBufferHistoryService.findOne(id);
  }

