import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateLogBufferHistoryDto } from './dto/create-log-buffer-history.dto';
import { UpdateLogBufferHistoryDto } from './dto/update-log-buffer-history.dto';
import { LogBufferHistory } from './entities/log-buffer-history.entity';

@Injectable()
export class LogBufferHistoryService {
  public constructor(
    @InjectRepository(LogBufferHistory)
    private readonly logBufferHistoryRepository: Repository<LogBufferHistory>,
  ) {}

  /**
   * Create a single log buffer history record
   * @param createDto - DTO for creating log buffer history
   * @returns Created LogBufferHistory record
   */
  public async create(
    createDto: CreateLogBufferHistoryDto,
  ): Promise<LogBufferHistory> {
    const logEntry = this.logBufferHistoryRepository.create(createDto);
    return this.logBufferHistoryRepository.save(logEntry);
  }

  /**
   * Create multiple log buffer history records in bulk
   * @param createDtos - Array of DTOs for creating log buffer history
   * @returns Array of created LogBufferHistory records
   */
  public async createBulk(
    createDtos: Array<CreateLogBufferHistoryDto>,
  ): Promise<Array<LogBufferHistory>> {
    const logEntries = this.logBufferHistoryRepository.create(createDtos);
    return this.logBufferHistoryRepository.save(logEntries);
  }

  /**
   * Update a single log buffer history record
   * @param updateDto - DTO for updating log buffer history
   * @returns Updated LogBufferHistory record
   */
  public async update(
    updateDto: UpdateLogBufferHistoryDto,
  ): Promise<LogBufferHistory> {
    const { id, ...updateData } = updateDto;

    const existingLog = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!existingLog) {
      throw new NotFoundException(`Log buffer history with id ${id} not found`);
    }

    await this.logBufferHistoryRepository.update(id, updateData);

    const updatedLog = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!updatedLog) {
      throw new NotFoundException(
        `Log buffer history with id ${id} not found after update`,
      );
    }

    return updatedLog;
  }

  /**
   * Update multiple log buffer history records in bulk
   * @param updateDtos - Array of DTOs for updating log buffer history
   * @returns Array of updated LogBufferHistory records
   */
  public async updateBulk(
    updateDtos: Array<UpdateLogBufferHistoryDto>,
  ): Promise<Array<LogBufferHistory>> {
    return Promise.all(updateDtos.map((dto) => this.update(dto)));
  }

  /**
   * Find all log buffer history records
   * @returns Array of LogBufferHistory records
   */
  public async findAll(): Promise<Array<LogBufferHistory>> {
    return this.logBufferHistoryRepository.find({
      order: { createdAt: 'DESC' },
    });
  }

  /**
  /**
   * Find a single log buffer history record by id
   * @param id - LogBufferHistory record id
   * @returns LogBufferHistory record
   */
  public async findOne(id: number): Promise<LogBufferHistory> {
    const logEntry = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!logEntry) {
      throw new NotFoundException(`Log buffer history with id ${id} not found`);
    }

    return logEntry;
  }

  /**
   * Find log buffer history records by orderId
   * @param orderId - Order ID
   * @returns Array of LogBufferHistory records
   */
  public async findByOrderId(
    orderId: string,
  ): Promise<Array<LogBufferHistory>> {
    return this.logBufferHistoryRepository.find({
      where: { orderId },
      order: { createdAt: 'DESC' },
    });
  }

  /**
   * Find log buffer history records by plant
   * @param plant - Plant name
   * @returns Array of LogBufferHistory records
   */
  public async findByPlant(plant: string): Promise<Array<LogBufferHistory>> {
    return this.logBufferHistoryRepository.find({
      where: { plant },
      order: { createdAt: 'DESC' },
    });
  }

  /**
   * Find a processing log buffer history record by orderId and plant
   * @param orderId - Order ID
   * @param plant - Plant name
   * @returns LogBufferHistory record or null
   */
  public async findProcessingByOrderIdAndPlant(
    orderId: string,
    plant: string,
  ): Promise<LogBufferHistory | null> {
    return this.logBufferHistoryRepository.findOne({
      where: { orderId, plant, status: 'PROCESSING' },
    });
  }

  /**
  /**
   * Mark a log buffer history record as success
   * @param id - LogBufferHistory record id
   * @returns Updated LogBufferHistory record
   */
  public async markAsSuccess(id: number): Promise<LogBufferHistory> {
    const existingLog = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!existingLog) {
      throw new NotFoundException(`Log buffer history with id ${id} not found`);
    }

    await this.logBufferHistoryRepository.update(id, { status: 'SUCCESS' });

    const updatedLog = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!updatedLog) {
      throw new NotFoundException(
        `Log buffer history with id ${id} not found after update`,
      );
    }

    return updatedLog;
  }

  /**
   * Mark a log buffer history record as error
   * @param id - LogBufferHistory record id
   * @param errorMessage - Error message string
   * @returns Updated LogBufferHistory record
   */
  public async markAsError(
    id: number,
    errorMessage: string,
  ): Promise<LogBufferHistory> {
    const existingLog = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!existingLog) {
      throw new NotFoundException(`Log buffer history with id ${id} not found`);
    }

    await this.logBufferHistoryRepository.update(id, {
      status: 'ERROR',
      errorMessage,
    });

    const updatedLog = await this.logBufferHistoryRepository.findOne({
      where: { id },
    });

    if (!updatedLog) {
      throw new NotFoundException(
        `Log buffer history with id ${id} not found after update`,
      );
    }

    return updatedLog;
  }
}

