@ApiTags('Material DTL')
@Controller('material-dtl')
export class MaterialDTLController {
  public constructor(private readonly materialDtlService: MaterialDTLService) {}

  @ApiOperation({
    description:
      'This endpoint lets you get a material DTL of from a specific plant by material id ',
    summary: 'Get material DTL by plant and id',
  })
  @ApiOkResponse({
    description: 'The material DTL ',
    type: MaterialDtlResponseDTO,
  })
  @ApiNotFoundResponse({
    description: 'Material DTL Not Found.',

    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @Get('/getMaterialDtlById/:plant/:materialId')
  @UseFilters(MesGenericErrorFilter)
  public async getMaterialById(
    @Param() query: MaterialDtlParameterDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { materialId, plant } = query;
    // Retrieve the material by ID for the specific plant
    const result = await this.materialDtlService.getMaterialDtlById(
      materialId,
      plant,
    );
    return response.status(HttpStatus.OK).json(result);
  }

  @Post('/getSebangoByMaterialDtlByIds')
  @UseFilters(MesGenericErrorFilter)
  public async getSebangoByMaterialDtlByIds(
    @Body() request: SebangoByMaterialDtlByIdsRequestDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { plant, materialIds } = request;

    const result: Record<string, string> =
      await this.materialDtlService.getSebangoByMaterialDtlByIds(
        plant,
        materialIds,
      );

    return response.status(HttpStatus.OK).json(result);
  }

  @ApiOperation({
    description: 'This endpoint returns the list of materials.',
    summary: 'This endpoint returns the list of materials.',
  })
  @ApiParam({
    example: '1146',
    name: 'plant',
    required: true,
    type: String,
  })
  @ApiOkResponse({
    description: 'The Materials ',
    type: Array<string>,
  })
  @ApiNotFoundResponse({
    description: 'Picking Order Not Found.',
    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @ApiTags('Material DTL')
  @Get('/getMaterialDtlByPlant/:plant')
  @UseFilters(MesGenericErrorFilter)
  public async getMaterialByPlant(
    @Param('plant') plant: number,
    @Res() response: Response,
  ): Promise<Response> {
    // Retrieve the material by ID for the specific plant
    const result = await this.materialDtlService.getMaterialDtlByPlant(plant);
    return response.status(HttpStatus.OK).json(result);
  }
}

