import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { MaterialGroup } from '../material-group/material-group.entity';
import { MaterialGroupResultDTO } from './dtos/material-group-result.dto';
import { MaterialGroupMember } from './material-group-member.entity';

@Injectable()
export class MaterialService {
  public constructor(
    @InjectRepository(MaterialGroupMember)
    private readonly materialGroupMemberRepository: Repository<MaterialGroupMember>,

    @InjectRepository(MaterialGroup)
    private readonly materialGroupRepository: Repository<MaterialGroup>,
  ) {}

  public async findMaterialGroupAndBbbMode(
    materialId: string,
    plant: number,
  ): Promise<MaterialGroupResultDTO> {
    // If numeric, pad to 18 digits; otherwise use as-is
    const queryMaterialId = /^\d+$/.test(materialId)
      ? materialId.padStart(18, '0')
      : materialId;

    // Single database query
    const materialGroupMember =
      await this.materialGroupMemberRepository.findOne({
        where: { materialId: queryMaterialId, plant },
      });

    if (!materialGroupMember) {
      throw new Error('MaterialGroupMember not found');
    }
    const materialGroup = await this.materialGroupRepository.findOne({
      where: { materialGroup: materialGroupMember.materialGroup, plant },
    });

    if (!materialGroup) {
      throw new Error('MaterialGroup not found');
    }

    return {
      bbbMode: materialGroup.bbbMode,
      materialGroup: materialGroupMember.materialGroup,
    };
  }
}

