@Injectable()
export class PickingOrderCommentHistoryService {
  public constructor(
    @InjectRepository(PickingOrderCommentHistory)
    private readonly pickingOrderCommentHistoryRepository: Repository<PickingOrderCommentHistory>,
  ) {}

  public async findAll(
    userId: number,
  ): Promise<Array<PickingOrderCommentHistory>> {
    try {
      // Fetch all history entries for this user and these comments
      const histories = await this.pickingOrderCommentHistoryRepository.find({
        where: { userId },
      });
      return histories;
    } catch (error) {
      throw new Error(`Error fetching comment histories: ${error.message}`);
    }
  }

  public async findAllByCommentIds(
    commentIds: Array<number>,
    userId: number,
  ): Promise<Array<PickingOrderCommentHistory>> {
    // Fetch all history entries for this user and these comments
    const histories = await this.pickingOrderCommentHistoryRepository
      .createQueryBuilder('history')
      .select([
        'history.commentId AS commentId',
        'history.userId AS userId',
        'history.lastReadAt AS lastReadAt',
      ])
      .where('history.commentId IN (:...commentIds)', { commentIds })
      .andWhere('history.userId = :userId', { userId })
      .getRawMany();

    return histories;
  }

  public async updateHistoryComments(
    userId: number,
    commentIds: Array<number>,
  ): Promise<void> {
    try {
      if (commentIds.length === 0) return;
      const lastReadAt: Date = new Date();

      const entities = commentIds.map((commentId) => ({
        userId,
        commentId: { id: commentId }, // If commentId is a relation
        lastReadAt,
      }));
      await this.pickingOrderCommentHistoryRepository.save(entities);
    } catch (error) {
      throw new Error(`Error updating comment histories: ${error.message}`);
    }
  }
}

