import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { PickingOrderCommentHistoryService } from '../picking-order-comment-history/picking-order-comment-history.service';
import { CreatePickingOrderCommentDto } from './dtos/create-picking-order-comment.dto';
import { PickingOrderComment } from './picking-order-comment.entity';

@Injectable()
export class PickingOrderCommentService {
  public constructor(
    @InjectRepository(PickingOrderComment)
    private readonly pickingOrderCommentRepository: Repository<PickingOrderComment>,

    private readonly pickingOrderCommentHistoryService: PickingOrderCommentHistoryService,
  ) {}

  public async create(
    createDto: CreatePickingOrderCommentDto,
  ): Promise<PickingOrderComment> {
    const { comment, userId, plant, pickingOrderId } = createDto;

    const pickingOrderComment = this.pickingOrderCommentRepository.create({
      comment,
      pickingOrder: { pickingOrderId, plant },
      plant,
      userId,
    });

    return this.pickingOrderCommentRepository.save(pickingOrderComment);
  }

  public async findAllByPickingOrder(
    pickingOrderId: string,
    plant: number,
  ): Promise<Array<PickingOrderComment>> {
    try {
      const comments = await this.pickingOrderCommentRepository.find({
        relations: ['pickingOrder'],
        select: {
          comment: true,
          createdAt: true,
          id: true,
          pickingOrder: {
            pickingOrderId: true,
          },
          plant: true,
          userId: true,
        },
        where: { pickingOrder: { pickingOrderId, plant } },
      });
      return comments;
    } catch (error) {
      throw new Error(`Error fetching comments: ${error.message}`);
    }
  }

  public async findAllByPickingOrderWithReadStatus(
    pickingOrderId: string,
    plant: number,
    userId: number,
  ): Promise<Array<PickingOrderComment & { isRead: boolean }>> {
    try {
      // Fetch all comments for the picking order
      const comments = await this.pickingOrderCommentRepository
        .createQueryBuilder('comment')
        .innerJoin('comment.pickingOrder', 'pickingOrder')
        .where('pickingOrder.pickingOrderId = :pickingOrderId', {
          pickingOrderId,
        })
        .andWhere('pickingOrder.plant = :plant', { plant })
        .select([
          'comment.id AS id',
          'comment.plant AS plant',
          'comment.comment AS comment',
          'comment.userId AS userId',
          'comment.createdAt AS createdAt',
        ])
        .getRawMany();

      if (comments.length === 0) return [];

      const commentIds = comments.map((c) => c.id);

      const histories =
        await this.pickingOrderCommentHistoryService.findAllByCommentIds(
          commentIds,
          userId,
        );
      let readCommentIds = new Set<number>();
      if (histories) {
        readCommentIds = new Set<number>(
          histories.map((h) => Number(h.commentId)).filter((id) => !!id),
        );
      }
      // Attach isRead to each comment
      return comments.map((comment) => ({
        ...comment,
        isRead: readCommentIds.has(comment.id) || comment.userId === userId, // Check if the comment ID is in the read set
      }));
    } catch (error) {
      throw new Error(
        `Error fetching comments with read status: ${error.message}`,
      );
    }
  }

  public async countCommentsByReadStatusAndNotCommentedByUser(
    pickingOrderList: Array<string>,
    plant: number,
    userId: number,
  ): Promise<Record<string, number>> {
    // This query counts comments for each pickingOrderId that are NOT read by the user and NOT created by the user
    const rows = await this.pickingOrderCommentRepository
      .createQueryBuilder('comment')
      .innerJoin('comment.pickingOrder', 'pickingOrder')
      .leftJoin(
        'picking_order_comment_history',
        'history',
        'history.commentId = comment.id AND history.userId = :userId',
        { userId },
      )
      .where('pickingOrder.pickingOrderId IN (:...pickingOrderList)', {
        pickingOrderList,
      })
      .andWhere('pickingOrder.plant = :plant', { plant })
      .andWhere('comment.userId != :userId', { userId })
      .andWhere('history.commentHistoryId IS NULL') // Only comments not read by user
      .select([
        'pickingOrder.pickingOrderId AS pickingOrderId',
        'COUNT(comment.id) AS notReadCount',
      ])
      .groupBy('pickingOrder.pickingOrderId')
      .getRawMany();

    // Map results to the expected output format, ensuring all pickingOrderIds are present
    const result: Record<string, number> = {};
    for (const id of pickingOrderList) {
      const row = rows.find((r) => r.pickingOrderId === id);
      result[id] = row ? Number(row.notReadCount) : 0;
    }
    return result;
  }

  /**
   * Check if a comment exists for the given picking orders, plant, and userId = 0
   * @param pickingOrderIds - list of picking order IDs
   * @param plant - plant number
   * @returns boolean indicating existence
   */
  public async doesCommentExist(
    pickingOrderIds: Array<string>,
    plant: number,
  ): Promise<boolean> {
    const count = await this.pickingOrderCommentRepository.count({
      where: {
        pickingOrder: {
          pickingOrderId: In(pickingOrderIds),
          plant,
        },
        userId: 0,
      },
    });

    return count > 0;
  }
}

