/**
 * Parses a JSON string of rescheduler work histories into an array of DTOs,
 * and normalizes all date strings to ISO format with UTC (Z suffix).
 * @param jsonString - The JSON string representing rescheduler work histories.
 * @returns An array of ReschedulerWkHistoryForOrdersResponse objects.
 */
export function parseReschedulerWkHistoriesFromJson(
  jsonString: string,
): Array<ReschedulerWkHistoryForOrdersResponse> {
  if (!jsonString) return [];

  try {
    const parsed = JSON.parse(jsonString);
    if (!Array.isArray(parsed)) return [];

    // Normalize timestamp fields to ISO strings
    const normalized = parsed.map((item) => ({
      ...item,
      oldPickingTime: item.oldPickingTime
        ? new Date(item.oldPickingTime)
        : undefined,
      newPickingTime: item.newPickingTime
        ? new Date(item.newPickingTime)
        : undefined,
      alertCreationTime: item.alertCreationTime
        ? new Date(item.alertCreationTime)
        : undefined,
    }));

    return plainToInstance(ReschedulerWkHistoryForOrdersResponse, normalized);
  } catch (error) {
    console.error('Failed to parse reschedulerWkHistories JSON:', error);
    return [];
  }
}

import { plainToInstance } from 'class-transformer';
import { ReschedulerWkHistoryForOrdersResponse } from '@/modules/picking-order/dtos/rescheduler-wk-history-for-order-response.dto';

/**
 * Parses the rescheduler work histories string into an array of ReschedulerWkHistoryForOrdersResponse objects.
 * @param reschedulerWkHistories - The string containing rescheduler work histories.
 * @returns An array of ReschedulerWkHistoryForOrdersResponse objects.
 */
export function parseReschedulerWkHistories(
  reschedulerWkHistories: string,
): Array<ReschedulerWkHistoryForOrdersResponse> {
  if (!reschedulerWkHistories) return [];

  return reschedulerWkHistories.split(';').map((entry) => {
    const fields: Record<string, string> = {};

    // Match key-value pairs correctly with regex
    for (const pair of entry.split(',')) {
      const separatorIndex = pair.indexOf(':');
      if (separatorIndex !== -1) {
        const key = pair.slice(0, Math.max(0, separatorIndex)).trim();
        const value = pair.slice(Math.max(0, separatorIndex + 1)).trim();
        fields[key] = value;
      }
    }

    return plainToInstance(ReschedulerWkHistoryForOrdersResponse, {
      alertCreationTime: fields.alertCreationTime
        ? new Date(fields.alertCreationTime)
        : undefined,
      comment: fields.comment || '',
      newPickingTime: fields.newPickingTime
        ? new Date(fields.newPickingTime)
        : undefined,
      oldPickingTime: fields.oldPickingTime
        ? new Date(fields.oldPickingTime)
        : undefined,
      reschedulerWkHistoryId: fields.reschedulerWkHistoryId
        ? Number(fields.reschedulerWkHistoryId)
        : undefined,
    });
  });
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PlantConfig } from '../plant-config/plant-config.entity';
import { PickingOrderJobOptionsDto } from './dtos/picking-order-job-options.dto';
import { PickingOrder } from './picking-order.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class PickingOrderCleanupService {
  private readonly logger = new AppLogger(PickingOrderCleanupService.name);

  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingOrderRepo: Repository<PickingOrder>,
    @InjectRepository(PlantConfig)
    private readonly plantConfigRepo: Repository<PlantConfig>,
  ) {}

  public async runDeletePickingOrderProcedure(
    plantCode: number,
    options?: PickingOrderJobOptionsDto,
  ): Promise<void> {
    try {
      const parameters: [string | number] = [plantCode];
      const sqlParts: Array<string> = [
        'EXEC dbo.usp_cleanup_picking_order_closed @PlantCode = @0',
      ];

      let parameterIndex = 1;

      if (options?.months !== undefined) {
        sqlParts.push(`@Months = @${parameterIndex}`);
        parameters.push(options.months);
        parameterIndex += 1;
      }

      if (options?.nbRowsToClean !== undefined) {
        sqlParts.push(`@NbRowsToClean = @${parameterIndex}`);
        parameters.push(options.nbRowsToClean);
        parameterIndex += 1;
      }

      if (options?.batchSize !== undefined) {
        sqlParts.push(`@BatchSize = @${parameterIndex}`);
        parameters.push(options.batchSize);
        parameterIndex += 1;
      }

      if (options?.delayMSBetweenRuns !== undefined) {
        sqlParts.push(`@DelayMSBetweenRuns = @${parameterIndex}`);
        parameters.push(options.delayMSBetweenRuns);
      }

      const sql = sqlParts.join(', ');

      await this.pickingOrderRepo.query(sql, parameters);
    } catch (error) {
      this.logger.error(
        `Failed to execute dbo.usp_cleanup_picking_order_closed for plant ${plantCode}: ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }

  public async runDeletePickingOrderProcedureForAllPlants(
    options?: PickingOrderJobOptionsDto,
  ): Promise<void> {
    try {
      // Fetch all plants from plant_config table
      const plantConfigs = await this.plantConfigRepo.find({
        select: ['plant'],
      });

      if (!plantConfigs || plantConfigs.length === 0) {
        this.logger.warn('No plants found in plant_config table');
        return;
      }

      this.logger.log(
        `Starting cleanup procedure for ${plantConfigs.length} plants`,
      );

      // Run cleanup sequentially for each plant
      for (const plantConfig of plantConfigs) {
        this.logger.log(
          `Running cleanup procedure for plant ${plantConfig.plant}`,
        );
        await this.runDeletePickingOrderProcedure(plantConfig.plant, options);
        this.logger.log(
          `Cleanup procedure completed for plant ${plantConfig.plant}`,
        );
      }

      this.logger.log('Cleanup procedure completed for all plants');
    } catch (error) {
      this.logger.error(
        `Failed to execute cleanup procedure for all plants: ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }
}

