@Injectable()
export class PickingOrderRepository {
  private readonly logger = new AppLogger(PickingOrderRepository.name);

  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingOrderRepo: Repository<PickingOrder>,
    @InjectDataSource() private readonly dataSource: DataSource,
    private readonly alertService: AlertService,
  ) {}

  public async getOrdersByrelatedLabel(
    plant: number,
    containerId: Array<string>,
  ): Promise<Array<PickingOrder>> {
    try {
      const orders = await this.pickingOrderRepo.find({
        where: {
          plant,
          relatedLabel: In(containerId),
        },
      });

      if (!orders) {
        return [];
      }

      return orders;
    } catch (error) {
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve picking orders by related label:',
              error,
            );
      throw errorException;
    }
  }

  public async findOutboundsByOrderIds(
    orderIds: Array<string>,
    plant: number,
  ): Promise<Array<{ orderId: string; outbounds: Array<string> }>> {
    try {
      // Fetch all orders at once using a single query with a WHERE IN condition
      const orders = await this.pickingOrderRepo.find({
        select: ['pickingOrderId', 'outbound'],
        where: { pickingOrderId: In(orderIds), plant },
      });

      // Group the orders by orderId
      const results = orderIds.map((orderId) => {
        const outbounds = orders
          .filter((order) => order.pickingOrderId === orderId) // Filter orders by orderId
          .map((order) => order.outbound) // Map the results to outbounds
          .filter((outbound) => !!outbound); // Remove any null/undefined outbounds

        return { orderId, outbounds };
      });

      return results;
    } catch (error) {
      AppLogger.error(
        'Error occurred while retrieving outbounds for order IDs:',
        error,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve outbounds for provided order IDs',
      );
    }
  }

  public async getPickingOrdersByFilter(
    filterDTO: PickingOrderFilterDTO,
  ): Promise<Array<PickingOrder>> {
    try {
      const queryBuild = this.pickingOrderRepo
        .createQueryBuilder('po') // Alias for table picking_order
        .where('po.plant = :plant', {
          plant: filterDTO.plant,
        });

      // Build dynamically the WHERE clause based on the received optional filters
      const dynamicFilters = {
        agvAssigned: 'po.agvAssigned = :agvAssigned',
        alertCreated: 'po.alertCreated = :alertCreated',
        batch: 'po.batch = :batch',
        batchTest: 'po.batchTest = :batchTest',
        containerNumber: 'po.containerNumber = :containerNumber',
        createdAtFrom: 'po.createdAt >= :createdAtFrom',
        createdAtTo: 'po.createdAt <= :createdAtTo',
        customStatus: 'po.customStatus IN (:...customStatus)',
        customStatusToBeExcluded:
          'po.customStatus NOT IN (:...customStatusToBeExcluded)',
        customer: 'po.customer = :customer',
        destinationLocation: 'po.destinationLocation = :destinationLocation',
        destinationWc: 'po.destinationWc = :destinationWc',
        endPreparationTimeFrom:
          'po.endPreparationTime >= :endPreparationTimeFrom',
        endPreparationTimeTo: 'po.endPreparationTime <= :endPreparationTimeTo',
        endProductionTimeFrom: 'po.endProductionTime >= :endProductionTimeFrom',
        endProductionTimeTo: 'po.endProductionTime <= :endProductionTimeTo',
        material: 'po.material = :material',
        outbound: 'po.outbound IN (:...outbound)',
        pickingOrderId: 'po.pickingOrderId = :pickingOrderId',
        pikNumber: 'po.pikNumber = :pikNumber',
        plannedCompDateFrom: 'po.plannedCompDate >= :plannedCompDateFrom',
        plannedCompDateTo: 'po.plannedCompDate <= :plannedCompDateTo',
        plannedStartDateFrom: 'po.plannedStartDate >= :plannedStartDateFrom',
        plannedStartDateTo: 'po.plannedStartDate <= :plannedStartDateTo',
        qtyDone: 'po.qtyDone = :qtyDone',
        qtyScrapped: 'po.qtyScrapped = :qtyScrapped',
        qtyToBuild: 'po.qtyToBuild = :qtyToBuild',
        relatedLabel: 'po.relatedLabel = :relatedLabel',
        relatedOrder: 'po.relatedOrder = :relatedOrder',
        rescheduled: 'po.rescheduled = :rescheduled',
        scheduledCompDateFrom: 'po.scheduledCompDate >= :scheduledCompDateFrom',
        scheduledCompDateTo: 'po.scheduledCompDate <= :scheduledCompDateTo',
        scheduledStartDateFrom:
          'po.scheduledStartDate >= :scheduledStartDateFrom',
        scheduledStartDateTo: 'po.scheduledStartDate <= :scheduledStartDateTo',
        sourceLocation: 'po.sourceLocation = :sourceLocation',
        status: 'po.status = :status',
        tpaNumber: 'po.tpaNumber = :tpaNumber',
        truckDepartureTimeFrom:
          'po.truckDepartureTime >= :truckDepartureTimeFrom',
        truckDepartureTimeTo: 'po.truckDepartureTime <= :truckDepartureTimeTo',
        updatedAtFrom: 'po.updatedAt >= :updatedAtFrom',
        updatedAtTo: 'po.updatedAt <= :updatedAtTo',
        wmsAssigned: 'po.wmsAssigned = :wmsAssigned',
        workcenter: 'po.workcenter = :workcenter',
      };

      for (const [key, condition] of Object.entries(dynamicFilters)) {
        const value = filterDTO[key as keyof PickingOrderFilterDTO];
        if (value !== undefined && value !== null) {
          queryBuild.andWhere(condition, { [key]: value });
        }
      }

      // This reads the columns of outbound_delivery table as defined in the entity OutboundDelivery
      const entityColumns = this.dataSource
        .getMetadata(PickingOrder)
        .columns.map((col) => `po.${col.propertyName} AS ${col.propertyName}`);

      // This creates a list of unique valid (part of entity) columns from the list of
      // Columns specified by caller in the filterDTO in order to avoid issue by inexistent/duplicate column specified in filterDTO
      const selectedColumns = [...new Set(filterDTO.outputColumns || [])] // This part removes duplicates
        .map((col) => `po.${col} AS ${col}`)
        .filter((col) => entityColumns.includes(col));

      const finalSelection =
        selectedColumns.length > 0 ? selectedColumns : entityColumns; // Defaults to returning full list of columns if nothing valid was specified

      // GetRawMany() was chosen for performance reasons. No need to instantiate objects (as getMany() does) for each returned record since we only need the plain text details
      const result = await queryBuild
        .select(finalSelection)
        .orderBy('po.createdAt', 'ASC')
        .limit(filterDTO.rowCount ?? 100)
        .getRawMany();

      // Always return the mapped array, even if empty
      return result;
    } catch (error) {
      // Log the error and return an empty array as a fallback
      this.logger.error(
        `Failed to retrieve picking order details: ${error.message}`,
      );
      return [];
    }
  }

  public async updateAlertedWK(
    plant: number,
    pickingOrderId: string,
  ): Promise<string | undefined> {
    let message = '';
    try {
      const creteria = { pickingOrderId, plant };
      const newValue = { alertCreated: true };

      const result = await this.pickingOrderRepo.update(creteria, newValue);
      if (result.affected && result.affected > 0) {
        message = 'SUCCESS';
        return message;
      }
      message = 'ERROR';
      return message;
    } catch (error) {
      message = `Failed to update picking order: ${error.message}`;
      return message;
    }
  }

  public async getOrdersByDateWithRescheduling(
    plant: number,
    date: Date,
    notClosed: boolean | undefined,
    maxDate: Date | undefined,
  ): Promise<Array<PickingOrderWithReschedulingList>> {
    try {
      let query = `
      WITH CombinedReschedulerHistory AS (
    SELECT 
        r.picking_order_id,
        r.plant,
        r.updated_at,
        r.new_picking_time,
        r.rescheduler_wk_history_id,
        r.alert_creation_time,
        r.old_picking_time,
        r.comment,
        ROW_NUMBER() OVER (PARTITION BY r.picking_order_id ORDER BY r.updated_at DESC) AS rn
    FROM rescheduler_wk_history r
    WHERE r.plant = @0
),
GroupedReschedulerHistory AS (
    SELECT 
        r.picking_order_id,
        r.plant,
        STRING_AGG(
            CONCAT(
                'reschedulerWkHistoryId: ', r.rescheduler_wk_history_id, 
                ', alertCreationTime: ', FORMAT(r.alert_creation_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                ', newPickingTime: ', FORMAT(r.new_picking_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                ', oldPickingTime: ', FORMAT(r.old_picking_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                ', comment: ', r.comment
            ), 
            '; '
        ) AS all_rwh_entries
    FROM rescheduler_wk_history r
    WHERE r.plant = @0
    GROUP BY r.picking_order_id, r.plant
)
SELECT  
    po.plant AS plant,
    po.picking_order_id AS pickingOrderId,
    po.material AS material,
    po.workcenter AS workcenter,
    po.status AS status,
    po.custom_status AS customStatus,
    po.pik_number AS pikNumber,
    po.source_location AS sourceLocation,
    po.destination_location AS destinationLocation,
    po.outbound AS outbound,
    po.customer AS customer,
    po.tpa_number AS tpaNumber,
    po.related_order AS relatedOrder,
    po.related_label AS relatedLabel,
    po.container_number AS containerNumber,
    po.planned_comp_date AS plannedCompDate,
    po.planned_start_date AS plannedStartDate,
    po.end_production_time AS endProductionTime,
    po.scheduled_comp_date AS scheduledCompDate,
    po.truck_departure_time AS truckDepartureTime,
    po.end_preparation_time AS endPreparationTime,
    po.alert_created AS alertCreated,
    po.updated_at AS pickingOrderUpdatedAt,
    alert.alert_id AS alertId,
    alert.alert_status AS alertStatus,
    alert_level AS alertLevel,
    alert.created_at AS alertCreationTime,
    crh.new_picking_time AS newPromiseTime,
    grh.all_rwh_entries AS reschedulerWkHistories
FROM picking_order po
LEFT JOIN CombinedReschedulerHistory crh
    ON po.picking_order_id = crh.picking_order_id 
    AND po.plant = crh.plant
    AND crh.rn = 1
LEFT JOIN GroupedReschedulerHistory grh
    ON po.picking_order_id = grh.picking_order_id 
    AND po.plant = grh.plant
LEFT JOIN alert 
    ON po.picking_order_id = alert.picking_order_id 
    AND po.plant = alert.plant
    `;
      let parameter = [plant, date];
      query += maxDate
        ? ` WHERE po.plant = @0 AND (
        (po.updated_at < @2 AND po.updated_at > @1) OR
        (alert.updated_at < @2  AND alert.updated_at > @1) OR
        (crh.updated_at < @2  AND crh.updated_at > @1)
      )`
        : ` WHERE po.plant = @0 AND (po.updated_at > @1 
       OR alert.updated_at > @1
       OR crh.updated_at > @1) `;
      if (notClosed) {
        query += ` AND po.custom_status <> 'CLOSED' AND po.status not in ('504','503') AND po.custom_status <> ''`;
      }
      if (maxDate) {
        parameter = [plant, date, maxDate];
      }
      const ordersRaw: Array<PickingOrderWithReschedulingList> =
        await this.pickingOrderRepo.query(query, parameter);

      if (!ordersRaw) {
        throw new NotFoundException('Picking Orders not found');
      }
      const orders = ordersRaw.map((order) => {
        const reschedulerWkHistories = parseReschedulerWkHistories(
          order.reschedulerWkHistories as unknown as string,
        );
        return plainToInstance(PickingOrderWithReschedulingList, {
          ...order,
          reschedulerWkHistories,
        });
      });
      return orders;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve picking orders with rescheduling: ${error.message}`,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve picking orders with rescheduling',
        error,
      );
    }
  }

  public async getPickingOrdersRequiringAlert(
    plant: number,
    workcenters: Array<string>,
  ): Promise<{ shopOrders: Array<PickingOrderResponseDTO>; dateNow: Date }> {
    try {
      const dateNow = new Date();
      const shopOrders = await this.pickingOrderRepo
        .createQueryBuilder('order')
        .leftJoinAndSelect(
          ReschedulerWkHistory,
          'rescheduler_wk_history',
          'order.plant = rescheduler_wk_history.plant AND order.pickingOrderId = rescheduler_wk_history.pickingOrderId',
        )
        .where('order.alertCreated = :alertCreated', { alertCreated: false })
        .andWhere('order.customStatus NOT IN (:...excludedStatuses)', {
          excludedStatuses: [
            '',
            'PICKED',
            'PALLETIZED',
            'PIK_CLOSED',
            'CLOSED',
          ],
        })
        .andWhere(
          new Brackets((qb) => {
            qb.where('order.plannedStartDate < :now', { now: dateNow }).orWhere(
              'rescheduler_wk_history.new_picking_time < :now',
              { now: dateNow },
            );
          }),
        )
        .andWhere('order.plant = :plant', { plant })
        .andWhere('order.workcenter IN (:...workcenters)', { workcenters })
        .andWhere('order.status IN (:...statuses)', {
          statuses: ['501', '502'],
        })
        .andWhere("order.outbound IS NOT NULL AND order.outbound != ''")
        .orderBy('order.plannedStartDate', 'ASC')
        .limit(100)
        .getMany();

      return {
        shopOrders,
        dateNow,
      };
    } catch (error) {
      console.error(
        `Error fetching PickingOrders requiring alert for plant ${plant}:`,
        error,
      );
      throw new InternalServerErrorException(
        `Failed to fetch PickingOrders requiring alert for plant ${plant}. Please try again later.`,
      );
    }
  }

