  public async fetchAlertsRedBell(
    plant: string,
  ): Promise<Array<AlertEscalateResponseDTO>> {
    try {
      const queryBuilder = this.pickingOrderRepo
        .createQueryBuilder('po')
        .select([
          'po.picking_order_id AS pickingOrderId',
          'po.end_preparation_time AS endPreparation',
          'po.truck_departure_time AS truckDeparture',
          'po.plant AS plant',
          'alert.alert_id AS alertId',
          `'RED_BELL' AS alertEscalateLevel`,
          'alert.red_bell_sms AS redBellSms',
        ])
        .leftJoin(
          'rescheduler_wk_history',
          'rwh',
          'po.plant = rwh.plant AND po.picking_order_id = rwh.picking_order_id',
        )
        .innerJoin(
          'alert',
          'alert',
          "po.picking_order_id = alert.picking_order_id AND po.plant = alert.plant AND alert.alert_status != 'Closed'",
        )
        .innerJoin('plant_config', 'pc', 'po.plant = pc.plant')
        .where('po.custom_status != :customStatus', { customStatus: 'CLOSED' })
        .andWhere('po.status IN (:...statuses)', { statuses: ['501', '502'] })
        .andWhere('po.alert_created = :alertCreated', { alertCreated: 1 })
        .andWhere('po.plant = :plant', { plant })
        .andWhere('rwh.picking_order_id IS NULL')
        .andWhere(`alert.red_bell_sms = 0`)
        .andWhere(
          `
    DATEADD(MINUTE, pc.tolerance_value_wk, alert.created_at) < GETDATE()
    AND alert.alert_level = 'GREY'
    AND alert.alert_status = 'OPEN'
  `,
        )
        .limit(100); // Equivalent to TOP 100 in SQL

      const alerts = await queryBuilder.getRawMany();

      return alerts;
    } catch (error) {
      throw new Error(`Failed to fetch alerts with RED_BELL ${error}`);
    }
  }

