  public async getClosedPickingOrderIds(
    plant: number,
    from?: string,
    to?: string,
    fromLeveling?: boolean,
  ): Promise<Array<string>> {
    try {
      // Start building the query
      const queryBuilder = this.pickingOrderRepo
        .createQueryBuilder('po')
        .select('po.picking_order_id', 'id')
        .where('po.plant = :plant', { plant })
        .andWhere('po.status IN (:...statuses)', { statuses: ['503', '504'] }); // Only closed orders (status 503 or 504)

      if (fromLeveling) {
        queryBuilder.andWhere(
          `(
       (po.status = '503' AND po.planned_start_date < DATEADD(DAY, -7, GETDATE()))
       OR po.status = '504'
     )`,
        );
      }
      // If 'from' date is provided, add the condition for createdAt and updatedAt
      if (from) {
        const fromDate = new Date(from);
        queryBuilder.andWhere('po.updatedAt >= :fromDate', { fromDate });
      }
      // If 'to' date is provided, add the condition for createdAt and updatedAt
      if (to) {
        const toDate = new Date(to);
        queryBuilder.andWhere('po.updatedAt <= :toDate', { toDate });
      }
      const result = await queryBuilder.getRawMany();
      return result.map((row) => row.id);
    } catch (error) {
      console.error('Error in getClosedPickingOrderIds service:', error);
      throw new Error('Failed to fetch closed picking order IDs');
    }
  }

  public async getPickingOrdersCountGroupedByPlant(
    plantId: number | null, // No need for 'closed' parameter
  ): Promise<Record<string, number>> {
    // Use Record instead of Map
    // WhereClause with non-closed status (default logic)
    const queryBuilder = this.pickingOrderRepo
      .createQueryBuilder('po')
      .select('po.plant', 'plant')
      .addSelect('COUNT(po.picking_order_id)', 'orderCount')
      .where('po.status NOT IN (:...statuses)', { statuses: ['503', '504'] })
      .andWhere('po.custom_status != :customStatus', {
        customStatus: '',
      });

    if (plantId) {
      queryBuilder.andWhere('po.plant = :plantId', { plantId });
    }
    queryBuilder.groupBy('po.plant');

    // Run query and get raw results
    const result = await queryBuilder.getRawMany();

    // Initialize an object to store the counts
    const plantCounts: Record<string, number> = {};

    // Process each row to extract plant and orderCount
    for (const row of result) {
      const plant = String(row['plant']); // Extract plant as string
      const count = Number(row['orderCount']); // Extract count as number
      plantCounts[plant] = count; // Add data to the object (instead of a Map)
    }
    // Return the plain object
    return plantCounts;
  }

  public async getOrdersByDateWithReschudeling(
    plant: number,
    date: Date,
  ): Promise<Array<PickingOrderResponseDTO>> {
    try {
      // Step 1: Retrieve orders from the repository
      const orders = await this.pickingOrderRepo.find({
        relations: ['reschedulerWkHistories'],
        where: {
          plant,
          updatedAt: MoreThanOrEqual(date),
        },
      });
      if (!orders || orders.length === 0) {
        throw new NotFoundException('Picking Orders not Found');
      }

      // Step 2: Extract pickingOrderId list from the orders
      const pickingOrderIds = orders.map((order) => order.pickingOrderId);

      // Step 3: Get the alerts based on pickingOrderIds and plant
      const alerts = await this.alertService.getAlertsByPickingOrderIds(
        plant,
        pickingOrderIds,
      );

      // Step 4: Map orders and include the alert data
      const ordersWithAlerts = orders.map((order) => {
        // Find the alert for the current order based on pickingOrderId
        const alert = alerts.find(
          (a) => a.pickingOrderId === order.pickingOrderId,
        );
        if (order.alertCreated) {
          if (alert) {
            return {
              ...order,
              alertCreationTime: alert.createdAt,
              alertId: alert.alertId,
              alertStatus: alert.alertStatus,
            };
          }
          return {
            ...order,
          };
        }
        return {
          ...order,
        };
      });

      return ordersWithAlerts;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve picking orders with rescheduling: ${error.message}`,
      );
      const errorException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve picking orders with rescheduling',
              error,
            );
      throw errorException;
    }
  }

  public async checkexistingPickingOrderList(
    plantId: number,
    pickingOrderList: Array<string>,
  ): Promise<Record<string, boolean>> {
    try {
      const existingOrders = await this.pickingOrderRepo.find({
        where: {
          plant: plantId,
          pickingOrderId: In(pickingOrderList),
        },
        select: ['pickingOrderId'],
      });

      const existingOrderIds = new Set(
        existingOrders.map((order) => order.pickingOrderId),
      );

      // Create a map to return the existence of each order
      const resultMap: Record<string, boolean> = {};
      for (const orderId of pickingOrderList) {
        resultMap[orderId] = existingOrderIds.has(orderId);
      }

      return resultMap;
    } catch {
      throw new InternalServerErrorException(
        'Failed to check existing picking orders',
      );
    }
  }

  public async fetchOrderByRange(
    plant: number,
    workcenter: string,
    range: number,
    startPickingTime: Date,
  ): Promise<Array<PickingOrder>> {
    try {
      const startRange = new Date(startPickingTime);
      const endRange = new Date(startRange.getTime() + range * 60 * 60 * 1000);
      const existingOrders = await this.pickingOrderRepo.find({
        where: {
          plant,
          workcenter,
          plannedStartDate: Between(startRange, endRange),
        },
      });
      return existingOrders;
    } catch {
      throw new InternalServerErrorException(
        'Failed to retrieve existing picking orders between range',
      );
    }
  }

  public async fetchOrderIdsByOutboundListAndPlant(
    plant: number,
    outbounds: Array<string>,
  ): Promise<Record<string, Array<string>>> {
    try {
      const orders = await this.pickingOrderRepo.find({
        where: {
          plant,
          outbound: In(outbounds),
        },
        select: ['pickingOrderId', 'outbound'],
      });
      // Create a map to return the existence of each order
      const resultMap: Record<string, Array<string>> = {};
      for (const order of orders) {
        if (!resultMap[order.outbound]) {
          resultMap[order.outbound] = [];
        }
        resultMap[order.outbound].push(order.pickingOrderId);
      }
      return resultMap;
    } catch {
      throw new InternalServerErrorException(
        `Failed to retrieve  picking orders linked to outbound ${outbounds} and plant ${plant} `,
      );
    }
  }

  public async fetchOrdersByWorkcenterListAndPlant(
    plant: number,
