  public async getOrdersByDateWithReschedulingVersionTriggers(
    plant: number,
    date: Date,
    maxDate?: Date,
    notClosed?: boolean,
  ): Promise<Array<PickingOrderWithHoldFlag>> {
    const parameters: Array<string | number | Date> = [plant, date];
    let query = `
    WITH TargetOrders AS (
      SELECT * 
      FROM picking_order
      WHERE plant = @0
        AND updated_at >= @1
  `;

    if (maxDate) {
      query += ` AND updated_at < @2`;
      parameters.push(maxDate);
    }

    if (notClosed) {
      query += `
      AND (
    (status NOT IN ('503', '504') AND custom_status <> '')
    OR (
      custom_status = 'CLOSED'
      AND status = '503'
      AND planned_start_date >= DATEADD(DAY, -7, GETDATE())
    )
  )
    `;
    }

    query += `
       ),
   LatestRescheduleHistory AS (
    SELECT o.picking_order_id,
           o.plant,
           r.new_picking_time,
           r.updated_at
    FROM TargetOrders o
    CROSS APPLY (
        SELECT TOP(1) rwh.new_picking_time,
                      rwh.updated_at
        FROM rescheduler_wk_history rwh
        WHERE rwh.picking_order_id = o.picking_order_id
          AND rwh.plant = o.plant
        ORDER BY rwh.updated_at DESC
    ) r
),

LatestAlert AS (
    SELECT o.picking_order_id,
           o.plant,
           a.alert_id,
           a.alert_status,
           a.alert_level,
           a.created_at,
           a.workcenter
    FROM TargetOrders o
    CROSS APPLY (
        SELECT TOP(1) a.alert_id,
                      a.alert_status,
                      a.alert_level,
                      a.created_at,
                      a.workcenter
        FROM alert a
        WHERE a.picking_order_id = o.picking_order_id
          AND a.plant = o.plant
        ORDER BY a.created_at DESC
    ) a
)
SELECT 
    po.plant,
    po.picking_order_id AS "pickingOrderId",
    po.material,
    po.workcenter,
    po.custom_status AS "customStatus",
    po.pik_number AS "pikNumber",
    po.source_location AS "sourceLocation",
    po.destination_location AS "destinationLocation",
    po.outbound,
    po.customer,
    po.tpa_number AS "tpaNumber",
    po.related_order AS "relatedOrder",
    po.related_label AS "relatedLabel",
    po.container_number AS "containerNumber",
    po.planned_comp_date AS "plannedCompDate",
    po.planned_start_date AS "plannedStartDate",
    po.end_production_time AS "endProductionTime",
    po.scheduled_comp_date AS "scheduledCompDate",
    po.truck_departure_time AS "truckDepartureTime",
    po.end_preparation_time AS "endPreparationTime",
    po.updated_at AS pickingOrderUpdatedAt,
    po.alert_created AS "alertCreated",
    po.status,
    po.batch,
    po.contains_hold_children AS "containsHoldChildren",
    la.alert_id AS "alertId",
    la.alert_status AS "alertStatus",
    la.alert_level AS "alertLevel",
    la.created_at AS "alertCreationTime",
    la.workcenter AS "sfgWorkcenter",
    lr.new_picking_time AS "newPromiseTime",
    lr_all.reschedulerWkHistories,
    lk.value AS "launcherWaitingTime"
FROM TargetOrders po
LEFT JOIN LatestRescheduleHistory lr 
    ON po.picking_order_id = lr.picking_order_id 
    AND po.plant = lr.plant
LEFT JOIN LatestAlert la 
    ON po.picking_order_id = la.picking_order_id 
    AND po.plant = la.plant
LEFT JOIN launcher_kpi lk
    ON po.plant = lk.plant
    AND po.workcenter = lk.workcenter
    AND lk.kpi_name = 'LAUNCHER_WAITING_TIME'
OUTER APPLY (
    SELECT (
      SELECT  
          rwh.rescheduler_wk_history_id AS "reschedulerWkHistoryId",
          rwh.old_picking_time AS "oldPickingTime",
          rwh.new_picking_time AS "newPickingTime",
          ISNULL(rwh.comment, '') AS comment,
          rwh.alert_creation_time AS "alertCreationTime"
      FROM rescheduler_wk_history rwh
      WHERE rwh.picking_order_id = po.picking_order_id
        AND rwh.plant = po.plant
      FOR JSON PATH
    ) AS reschedulerWkHistories
) AS lr_all
  `;
    const orders: Array<PickingOrderWithHoldFlag> =
      await this.pickingOrderRepo.query(query, parameters);
    return orders.map((order) => {
      const reschedulerWkHistories = parseReschedulerWkHistoriesFromJson(
        order.reschedulerWkHistories as unknown as string,
      );
      const launcherWaitingTimeObject =
        order.launcherWaitingTime === undefined
          ? undefined
          : { value: order.launcherWaitingTime };
      return plainToInstance(PickingOrderWithHoldFlag, {
        ...order,
        reschedulerWkHistories,
        launcherWaitingTime: launcherWaitingTimeObject,
      });
    });
  }

  public async getFilteredPickingData(
    filters: FilterDTO,
  ): Promise<Array<PickingOrder>> {
    const queryBuilder = this.pickingOrderRepo
      .createQueryBuilder('picking_order')
      .innerJoin(
        MaterialDtl,
        'material_dtl',
        'picking_order.material = material_dtl.materialId AND picking_order.plant = material_dtl.plant',
      )
      .where('picking_order.plant = :plant', { plant: filters.Plant });

    // Optional material filtering
    if (filters.Material && filters.Material.length > 0) {
      queryBuilder.andWhere('picking_order.material IN (:...material)', {
        materials: filters.Material,
      });
    }

    // Selecting all fields in PickingOrder entity with aliases
    queryBuilder.select([
      'picking_order.picking_order_id AS pickingOrderId',
      'picking_order.plant AS plant',
      'picking_order.material AS material',
      'picking_order.workcenter AS workcenter',
      'picking_order.status AS status',
      'picking_order.custom_status AS customStatus',
      'picking_order.pik_number AS pikNumber',
      'picking_order.source_location AS sourceLocation',
      'picking_order.destination_location AS destinationLocation',
      'picking_order.outbound AS outbound',
      'picking_order.tpa_number AS tpaNumber',
      'picking_order.related_label AS relatedLabel',
      'picking_order.container_number AS containerNumber',
      'picking_order.planned_comp_date AS plannedCompDate',
      'picking_order.scheduled_comp_date AS scheduledCompDate',
      'picking_order.created_date_time AS createdDateTime',
      'picking_order.planned_start_date AS plannedStartDate',
      'picking_order.customer AS customer',
      'picking_order.related_order AS relatedOrder',
      'picking_order.end_preparation_time AS endPreparationTime',
      'picking_order.truck_departure_time AS truckDepartureTime',
      'picking_order.rescheduled AS rescheduled',
      'picking_order.wms_assigned AS wmsAssigned',
      'picking_order.destination_wc AS destinationWc',
      'picking_order.scheduled_start_date AS scheduledStartDate',
      'picking_order.batch_test AS batchTest',
      'picking_order.batch AS batch',
      'picking_order.qty_scrapped AS qtyScrapped',
      'picking_order.qty_done AS qtyDone',
      'picking_order.qty_to_build AS qtyToBuild',
    ]);

    // Selecting specific fields in MaterialDtl with aliases
    queryBuilder.addSelect([
      'material_dtl.grouping_agv AS groupingAgv',
      'material_dtl.sebangoSap AS sebangoSap',
    ]);

    // Define the filtering logic
    const applyFilter = (
      field: string,
      value: unknown,
      operator = '=',
    ): void => {
      if (PickingOrderService.isValidFilter(value)) {
        // If the value is an array or object, handle it as an array
        if (
          PickingOrderService.isArrayFilter(value) &&
          operator !== 'BETWEEN'
        ) {
          // Use the 'IN' operator for array-like values
          queryBuilder.andWhere(`picking_order.${field} IN (:...${field})`, {
            [field]: value,
          });
        } else if (
          PickingOrderService.isArrayFilter(value) &&
          operator === 'BETWEEN' &&
          Array.isArray(value) &&
          value.length === 2
        ) {
          // Handle BETWEEN operator
          queryBuilder.andWhere(
            `picking_order.${field} BETWEEN :start AND :end`,
            {
              end: value[1],
              start: value[0],
            },
          );
        } else {
          // Standard filter
          queryBuilder.andWhere(
            `picking_order.${field} ${operator} :${field}`,
            {
              [field]: value,
            },
          );
        }
      }
    };
    // Apply filters using the helper function
    applyFilter('plant', Number(filters.Plant)); // Convert 'plant' to a number
    applyFilter('status', filters.Status, 'IN');
    applyFilter('customer', filters.Customer);
    applyFilter('agv_assigned', filters.AGVAssigned, 'IN');
    applyFilter('custom_status', filters.CustomStatus, 'IN');
    if (filters.StartPickingTime && filters.EndPickingTime) {
      applyFilter(
        'planned_start_date',
        [filters.StartPickingTime, filters.EndPickingTime],
        'BETWEEN',
      );
    } else if (filters.StartPickingTime) {
      applyFilter('planned_start_date', filters.StartPickingTime, '>=');
    } else if (filters.EndPickingTime) {
      applyFilter('planned_start_date', filters.EndPickingTime, '<=');
    }
    // Handle 'source_location' as an array or single value
    applyFilter('source_location', filters.FromStorageLoc, 'IN');

    applyFilter('material', filters.Material, 'IN');
    applyFilter('picking_order_id', filters.ShopOrder, 'IN');
    applyFilter('destination_location', filters.ToStorageLoc, 'IN');
    applyFilter('tpa_number', filters.TPA, 'IN');
    applyFilter('workcenter', filters.WorkCenter, 'IN');
    applyFilter('destination_wc', filters.DESTINATION_WC, 'IN');
    // Execute the query and return the result
    return queryBuilder.getRawMany();
  }

