  public async getWKByPlantAndOutbound(
    plant: number,
    outbound: string,
  ): Promise<Array<PickingOrderWithHoldFlag>> {
    try {
      const query = `
          WITH po AS (
  SELECT  
          po.plant AS plant,
          po.picking_order_id AS pickingOrderId,
          po.material AS material,
          po.workcenter AS workcenter,
          po.status AS status,
          po.custom_status AS customStatus,
          po.pik_number AS pikNumber,
          po.source_location AS sourceLocation,
          po.destination_location AS destinationLocation,
          po.outbound AS outbound,
          po.customer AS customer,
          po.tpa_number AS tpaNumber,
          po.related_order AS relatedOrder,
          po.related_label AS relatedLabel,
          po.container_number AS containerNumber,
          po.planned_comp_date AS plannedCompDate,
          po.planned_start_date AS plannedStartDate,
          po.end_production_time AS endProductionTime,
          po.scheduled_comp_date AS scheduledCompDate,
          po.truck_departure_time AS truckDepartureTime,
          po.end_preparation_time AS endPreparationTime,
          po.alert_created AS alertCreated,
          po.updated_at AS pickingOrderUpdatedAt,
          po.contains_hold_children AS "containsHoldChildren"
FROM picking_order po
      WHERE po.plant = @0 
        AND po.outbound = @1
),
grh AS (
          SELECT 
              r.picking_order_id,
              r.plant,
              STRING_AGG(
                  CONCAT(
                      'reschedulerWkHistoryId: ', r.rescheduler_wk_history_id, 
                      ', alertCreationTime: ', FORMAT(r.alert_creation_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                      ', newPickingTime: ', FORMAT(r.new_picking_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                      ', oldPickingTime: ', FORMAT(r.old_picking_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                      ', comment: ', r.comment
                  ), 
                  '; '
              ) AS all_rwh_entries
          FROM rescheduler_wk_history r
		  JOIN po ON r.picking_order_id = po.pickingOrderId AND r.plant = po.plant
          GROUP BY r.picking_order_id, r.plant
      )
	  SELECT po.*
          ,alert.alert_id AS alertId
          ,alert.alert_status AS alertStatus
          ,alert_level AS alertLevel
          ,alert.created_at AS alertCreationTime
, crh.new_picking_time AS newPromiseTime
, grh.all_rwh_entries
FROM po
LEFT JOIN grh ON po.pickingOrderId = grh.picking_order_id AND po.plant=grh.plant
LEFT JOIN alert 
          ON po.pickingOrderId = alert.picking_order_id 
          AND po.plant = alert.plant
OUTER APPLY (
          SELECT TOP(1)
              r.new_picking_time
          FROM rescheduler_wk_history r
		  WHERE r.picking_order_id = po.pickingOrderId AND r.plant = po.plant
		  ORDER BY r.picking_order_id DESC, r.plant DESC,  r.updated_at DESC
) crh
WHERE         po.customStatus <> 'CLOSED'
        AND po.status <> '504'
      `;

      const orders: Array<PickingOrderWithHoldFlag> =
        await this.pickingOrderRepo.query(query, [plant, outbound]);

      if (!orders || orders.length === 0) {
        return [];
      }

      return orders.map((order) => {
        const reschedulerWkHistories = parseReschedulerWkHistories(
          order.reschedulerWkHistories as unknown as string,
        );
        return plainToInstance(PickingOrderWithHoldFlag, {
          ...order,
          reschedulerWkHistories,
        });
      });
    } catch (error) {
      this.logger.error(
        `Failed to retrieve WK by plant and outbound: ${error.message}`,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve WK by plant and outbound',
        error,
      );
    }
  }

