  public async alertToBeEscalated(
    plant: number,
  ): Promise<Array<AlertEscalateResponseDTO>> {
    try {
      const latestPickingTimeSubquery = this.reschedulerWkHistoryRepo
        .createQueryBuilder('rwh')
        .select([
          'rwh.picking_order_id AS pickingOrderId',
          'rwh.plant AS plant',
          'rwh.new_picking_time AS newPickingTime',
          'ROW_NUMBER() OVER (PARTITION BY rwh.picking_order_id, rwh.plant ORDER BY rwh.created_at DESC) AS rowNum', // Used to identify the latest record per group
        ])
        .where('rwh.new_picking_time IS NOT NULL');

      const queryBuilder = this.pickingOrderRepo
        .createQueryBuilder('po')
        .select([
          'po.picking_order_id AS pickingOrderId',
          'po.outbound AS outbound',
          'po.plant AS plant',
          'lpt.newPickingTime AS newPickingTime',
          'alert.alert_id AS alertId',
          `CASE 
        WHEN lpt.newPickingTime < GETDATE() THEN 'Non-Acknowledged'
        WHEN lpt.newPickingTime > GETDATE() THEN 'Acknowledged'
        ELSE alert.alert_status
      END AS alertStatus`,
          'alert.yellow_sms AS yellowSms',
          'alert.red_sms AS redSms',
          'alert.orange_sms AS orangeSms',
        ])
        .innerJoin(
          `(${latestPickingTimeSubquery.getQuery()})`,
          'lpt',
          'po.picking_order_id = lpt.pickingOrderId AND po.plant = lpt.plant AND lpt.rowNum = 1',
        )
        .innerJoin(
          'alert',
          'alert',
          "po.picking_order_id = alert.picking_order_id AND po.plant = alert.plant AND alert.alert_status != 'Closed'",
        )
        .where('po.custom_status != :customStatus', { customStatus: 'CLOSED' })
        .andWhere('po.status IN (:...statuses)', { statuses: ['501', '502'] })
        .andWhere('po.alert_created = :alertCreated', { alertCreated: 1 })
        .andWhere('po.plant = :plant', { plant })
        .andWhere('po.outbound IS NOT NULL')
        .limit(100); // Equivalent to TOP 100 in SQL

      const pickingOrders = await queryBuilder.getRawMany();

      return pickingOrders;
    } catch (error) {
      console.error('Error in alertToBeEscalated:', error);
      throw new Error('Failed to fetch alerts to be escalated');
    }
  }

