  public async getPickingOrderDetails(
    pickingOrderDto: PickingOrderIdsDTO,
  ): Promise<Array<PickingOrderResponseDTO>> {
    try {
      const { pickingOrderIds, plant } = pickingOrderDto;

      if (pickingOrderIds.length === 0) {
        this.logger.warn('No picking order IDs provided');
        throw new NotFoundException('No Picking Order IDs provided');
      }

      const query = `
      WITH CombinedReschedulerHistory AS (
          SELECT 
              r.picking_order_id,
              r.plant,
              r.updated_at,
              r.new_picking_time,
              r.rescheduler_wk_history_id,
              r.alert_creation_time,
              r.old_picking_time,
              r.comment,
              ROW_NUMBER() OVER (PARTITION BY r.picking_order_id ORDER BY r.updated_at DESC) AS rn
          FROM rescheduler_wk_history r
          WHERE r.plant = @0
      ),
      GroupedReschedulerHistory AS (
          SELECT 
              r.picking_order_id,
              r.plant,
              STRING_AGG(
                  CONCAT(
                      'reschedulerWkHistoryId: ', r.rescheduler_wk_history_id, 
                      ', alertCreationTime: ', FORMAT(r.alert_creation_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                      ', newPickingTime: ', FORMAT(r.new_picking_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                      ', oldPickingTime: ', FORMAT(r.old_picking_time, 'yyyy-MM-dd HH:mm:ss.fff'), 
                      ', comment: ', r.comment
                  ), 
                  '; '
              ) AS all_rwh_entries
          FROM rescheduler_wk_history r
          WHERE r.plant = @0
          GROUP BY r.picking_order_id, r.plant
      )
      SELECT  
          po.plant AS plant,
          po.picking_order_id AS pickingOrderId,
          po.material AS material,
          po.workcenter AS workcenter,
          po.status AS status,
          po.custom_status AS customStatus,
          po.pik_number AS pikNumber,
          po.source_location AS sourceLocation,
          po.destination_location AS destinationLocation,
          po.outbound AS outbound,
          po.customer AS customer,
          po.tpa_number AS tpaNumber,
          po.related_order AS relatedOrder,
          po.related_label AS relatedLabel,
          po.container_number AS containerNumber,
          po.planned_comp_date AS plannedCompDate,
          po.planned_start_date AS plannedStartDate,
          po.end_production_time AS endProductionTime,
          po.scheduled_comp_date AS scheduledCompDate,
          po.truck_departure_time AS truckDepartureTime,
          po.end_preparation_time AS endPreparationTime,
          po.alert_created AS alertCreated,
          po.updated_at AS pickingOrderUpdatedAt,
          alert.alert_id AS alertId,
          alert.alert_status AS alertStatus,
          alert.alert_level AS alertLevel,
          alert.created_at AS alertCreationTime,
          crh.new_picking_time AS newPromiseTime,
          grh.all_rwh_entries AS reschedulerWkHistories
      FROM picking_order po
      LEFT JOIN CombinedReschedulerHistory crh
          ON po.picking_order_id = crh.picking_order_id 
          AND po.plant = crh.plant
          AND crh.rn = 1
      LEFT JOIN GroupedReschedulerHistory grh
          ON po.picking_order_id = grh.picking_order_id 
          AND po.plant = grh.plant
      LEFT JOIN alert 
          ON po.picking_order_id = alert.picking_order_id 
          AND po.plant = alert.plant
      WHERE po.plant = @0 
        AND po.picking_order_id IN (${pickingOrderIds.map((_, index) => `@${index + 1}`).join(', ')});
      `;
      const queryParameters = [plant, ...pickingOrderIds];
      const orders: Array<PickingOrderResponseDTO> =
        await this.pickingOrderRepo.query(query, queryParameters);

      if (!orders || orders.length === 0) {
        throw new NotFoundException('Picking Orders not found');
      }
      return orders.map((order) => {
        const reschedulerWkHistories = parseReschedulerWkHistories(
          order.reschedulerWkHistories as unknown as string,
        );
        return plainToInstance(PickingOrderResponseDTO, {
          ...order,
          reschedulerWkHistories,
        });
      });
    } catch (error) {
      this.logger.error(
        `Failed to retrieve picking order details: ${error.message}`,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve picking order details',
        error,
      );
    }
  }

