/**
 * This service provides methods to handle production orders, such as retrieving all orders, getting an order by ID, and finding the minimum sequence number by WK.
 */

// Import necessary modules and dependencies
import {
  BadRequestException,
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { FilterDTO } from '../buffer/dtos/filter-request.dto';
import { MaterialDtl } from '../material-dtl/material-dtl.entity';
import { PlantConfig } from '../plant-config/plant-config.entity';
import { ProductionOrderJobOptionsDto } from './dtos/production-order-job-options.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { SeqNumberResponse } from '@/modules/production-order/dtos/seq-number-response.dto';
import { ProductionOrder } from '@/modules/production-order/production-order.entity';
// Injectable decorator to mark the class as a service
@Injectable()
export class ProductionOrderService {
  // Utility function to check for valid filter values
  public static isValidFilter(value: unknown): boolean {
    return value !== undefined && value !== null && value !== '';
  }

  public static isArrayFilter(value: unknown): boolean {
    return (
      Array.isArray(value) || (typeof value === 'object' && value !== null)
    );
  }

  private readonly logger = new AppLogger(ProductionOrderService.name);

  public constructor(
    // Inject the repository for ProductionOrder entity
    @InjectRepository(ProductionOrder)
    private readonly productionOrderRepo: Repository<ProductionOrder>,
    @InjectRepository(PlantConfig)
    private readonly plantConfigRepo: Repository<PlantConfig>,
  ) {}

  // Method to find the minimum sequence number by WK for a specific plant and related order
  public async getMinSeqNumByPickingNumber(
    plant: number,
    relatedOrder: string,
  ): Promise<SeqNumberResponse> {
    try {
      // Execute a query to find the minimum sequence number
      const relatedOrderExists = await this.productionOrderRepo
        .createQueryBuilder('production_order')
        .where('production_order.relatedOrder = :relatedOrder', {
          relatedOrder,
        })
        .andWhere('production_order.plant = :plant', { plant })
        .getCount();
      if (relatedOrderExists > 0) {
        const result = await this.productionOrderRepo
          .createQueryBuilder('production_order')
          .select('MIN(production_order.seqNumber)', 'minSeqNum') // Select the minimum sequence number
          .where('production_order.relatedOrder = :relatedOrder', {
            relatedOrder,
          }) // Filter by related order
          .andWhere('production_order.plant = :plant', { plant }) // Filter by plant ID
          .getRawOne();

        if (!result?.minSeqNum) {
          throw new NotFoundException('Not Found MinSeq Number');
        }
        return result;
      }

      throw new NotFoundException('Related Order Not Found');

      // Related order does not exist
    } catch (error) {
      this.logger.error(
        `Failed to retrieve min seq number by picking order : ${error.message}`,
      );
      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve min seq number by picking order',
              error,
            );
      throw errorN;
    }
  }

  public async getMinSeqNumByRelatedOrders(
    plant: number,
    relatedOrders: Array<string>,
  ): Promise<Record<string, string>> {
    try {
      if (!relatedOrders || relatedOrders.length === 0) {
        throw new BadRequestException('No related orders provided');
      }

      const result = await this.productionOrderRepo
        .createQueryBuilder('production_order')
        .select('production_order.relatedOrder', 'relatedOrder')
        .addSelect('MIN(production_order.seqNumber)', 'minSeqNum')
        .where('production_order.relatedOrder IN (:...relatedOrders)', {
          relatedOrders,
        })
        .andWhere('production_order.plant = :plant', { plant })
        .andWhere('production_order.seqNumber is not null')
        .groupBy('production_order.relatedOrder')
        .getRawMany();

      if (!result || result.length === 0) {
        throw new NotFoundException(
          'No related orders found with min seq numbers',
        );
      }
      const response: Record<string, string> = {};
      for (const row of result) {
        response[row.relatedOrder] = row.minSeqNum;
      }

      return response;
    } catch (error) {
      const errorN =
        error instanceof NotFoundException ||
        error instanceof BadRequestException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve min seq numbers by related orders',
              error,
            );
      throw errorN;
    }
  }

  public async getFilteredProductionData(
    filters: FilterDTO,
  ): Promise<Array<unknown>> {
    const queryBuilder = this.productionOrderRepo
      .createQueryBuilder('production_order')
      .innerJoinAndSelect(
        MaterialDtl, // The MaterialDtl entity
        'material_dtl', // Alias for the joined table
        'production_order.material = material_dtl.materialId AND production_order.plant = material_dtl.plant', // Join condition
      )
      .where('production_order.plant = :plant', { plant: filters.Plant }) // Filter by plant
      // .andWhere('production_order.material IN (:...materials)', { materials : filters.material }) // Uncomment to filter by materials
      .select([
        'production_order.custom_status AS customStatus',
        'production_order.production_order_id AS productionOrderId',
        'production_order.material AS material',
        'production_order.workcenter AS workcenter',
        'production_order.seqNumber AS seqNumber',
        'production_order.planned_start_date AS plannedStartDate',
        'production_order.planned_comp_date AS plannedCompDate',
        'production_order.created_date_time AS createdDateTime',
        'production_order.scheduled_comp_date AS scheduledCompDate',
        'production_order.kanban_type AS kanbanType',
        'production_order.customer AS customer',
        'production_order.related_order AS relatedOrder',
        'production_order.plc_assigned AS plcAssigned',
        'material_dtl.grouping_agv AS groupingAgv',
        'material_dtl.sebangoSap AS sebangoSap',
        'production_order.qty_scrapped AS qtyScrapped',
        'production_order.qty_done AS qtyDone',
        'production_order.qty_to_build AS qtyToBuild',
        'production_order.batch AS batch',
      ]);
    const applyFilter = (
      field: string,
      value: unknown,
      operator = '=',
    ): void => {
      if (ProductionOrderService.isValidFilter(value)) {
        // If the value is an array or object, handle it as an array
        if (
          ProductionOrderService.isArrayFilter(value) &&
          operator !== 'BETWEEN'
        ) {
          // Use the 'IN' operator for array-like values
          queryBuilder.andWhere(`production_order.${field} IN (:...${field})`, {
            [field]: value,
          });
        } else if (
          ProductionOrderService.isArrayFilter(value) &&
          operator === 'BETWEEN' &&
          Array.isArray(value) &&
          value.length === 2
        ) {
          // Handle BETWEEN operator
          queryBuilder.andWhere(
            `production_order.${field} BETWEEN :start AND :end`,
            {
              end: value[1],
              start: value[0],
            },
          );
        } else {
          // Standard filter
          queryBuilder.andWhere(
            `production_order.${field} ${operator} :${field}`,
            {
              [field]: value,
            },
          );
        }
      }
    };
    applyFilter('kanban_type', filters.KanbanType);
    applyFilter('customer', filters.Customer);
    applyFilter('custom_status', filters.CustomStatus, 'IN');
    if (filters.StartPickingTime && filters.EndPickingTime) {
      applyFilter(
        'planned_start_date',
        [filters.StartPickingTime, filters.EndPickingTime],
        'BETWEEN',
      );
    } else if (filters.StartPickingTime) {
      applyFilter('planned_start_date', filters.StartPickingTime, '>=');
    } else if (filters.EndPickingTime) {
      applyFilter('planned_start_date', filters.EndPickingTime, '<=');
    }
    applyFilter('material', filters.Material, 'IN');
    applyFilter('production_order_id', filters.ShopOrder, 'IN');
    applyFilter('workcenter', filters.WorkCenter, 'IN');
    // Execute query and return result
    return queryBuilder.getRawMany();
  }

  public async getGhostByWorkcenters(
    plant: number,
    workcenters: Array<string>,
  ): Promise<Record<string, boolean>> {
    try {
      // Fetch matching workcenters from the database
      const foundWorkcenters = await this.productionOrderRepo
        .createQueryBuilder('po')
        .select('po.workcenter')
        .where('po.plant = :plant', { plant })
        .andWhere('po.kanban_type = :kanbanType', { kanbanType: 'GHOST' })
        .andWhere('po.custom_status != :customStatus', {
          customStatus: 'CLOSED',
        })
        .andWhere('po.workcenter IN (:...workcenters)', { workcenters })
        .getMany();

      // Convert the found workcenters to a Set for quick lookup
      const foundSet = new Set(
        foundWorkcenters.map((po: { workcenter: string }) => po.workcenter),
      );

      // Use a loop instead of .reduce()
      const result: Record<string, boolean> = {};
      for (const wc of workcenters) {
        result[wc] = foundSet.has(wc);
      }
      return result;
    } catch (error) {
      throw new InternalServerErrorException(
        'Error while checking workcenters existence for GHOST orders',
        error,
      );
    }
  }

  public async getPickingOrderWorkcenters(
    plant: number,
    pickingOrderIds: Array<string>,
  ): Promise<Record<string, string>> {
    try {
      if (!pickingOrderIds || pickingOrderIds.length === 0) {
        return {};
      }

      const rawResults = await this.productionOrderRepo
        .createQueryBuilder('po')
        .select([
          'orders.picking_order_id AS pickingOrderId',
          'po.workcenter AS workcenter',
        ])
        .innerJoin(
          'picking_order',
          'orders',
          'po.production_order_id = orders.pik_number AND orders.plant = :plant AND orders.picking_order_id IN (:...pickingOrderIds)',
          { pickingOrderIds, plant },
        )
        .getRawMany();

      const result: Record<string, string> = {};
      for (const row of rawResults) {
        result[row.pickingOrderId] = row.workcenter;
      }

      return result;
    } catch (error) {
      throw new InternalServerErrorException(
        'Failed to retrieve picking order workcenters',
        error,
      );
    }
  }

  public async runDeleteProductionOrderProcedure(
    plantCode: number,
    options?: ProductionOrderJobOptionsDto,
  ): Promise<void> {
    try {
      const parameters: [string | number] = [plantCode];
      const sqlParts: Array<string> = [
        'EXEC dbo.usp_cleanup_closed_production_orders @PlantCode = @0',
      ];

      let parameterIndex = 1;

      if (options?.months !== undefined) {
        sqlParts.push(`@Months = @${parameterIndex}`);
        parameters.push(options.months);
        parameterIndex += 1;
      }

      if (options?.nbRowsToClean !== undefined) {
        sqlParts.push(`@NbRowsToClean = @${parameterIndex}`);
        parameters.push(options.nbRowsToClean);
        parameterIndex += 1;
      }

      if (options?.batchSize !== undefined) {
        sqlParts.push(`@BatchSize = @${parameterIndex}`);
        parameters.push(options.batchSize);
        parameterIndex += 1;
      }

      if (options?.delayMSBetweenRuns !== undefined) {
        sqlParts.push(`@DelayMSBetweenRuns = @${parameterIndex}`);
        parameters.push(options.delayMSBetweenRuns);
      }

      const sql = sqlParts.join(', ');

      await this.productionOrderRepo.query(sql, parameters);
    } catch (error) {
      this.logger.error(
        `Failed to execute dbo.usp_cleanup_closed_production_orders for plant ${plantCode}: ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }

  public async runDeleteProductionOrderProcedureForAllPlants(
    options?: ProductionOrderJobOptionsDto,
  ): Promise<void> {
    try {
      // Fetch all plants from plant_config table
      const plantConfigs = await this.plantConfigRepo.find({
        select: ['plant'],
      });

      if (!plantConfigs || plantConfigs.length === 0) {
        this.logger.warn('No plants found in plant_config table');
        return;
      }

      this.logger.log(
        `Starting cleanup procedure for ${plantConfigs.length} plants`,
      );

      // Run cleanup sequentially for each plant
      for (const plantConfig of plantConfigs) {
        this.logger.log(
          `Running cleanup procedure for plant ${plantConfig.plant}`,
        );
        await this.runDeleteProductionOrderProcedure(
          plantConfig.plant,
          options,
        );
        this.logger.log(
          `Cleanup procedure completed for plant ${plantConfig.plant}`,
        );
      }

      this.logger.log('Cleanup procedure completed for all plants');
    } catch (error) {
      this.logger.error(
        `Failed to execute cleanup procedure for all plants: ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }
}

