import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AddReschedulerWkHistoryInMassDTO } from './dtos/add-rescheduler-wk-history-in-mass.dto';
import { ReschedulerWkInMassResponse } from './dtos/rescheduler-wk-in-mass.response.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { PickingOrderService } from '@/modules/picking-order/picking-order.service';
import { AddReschedulerWkHistoryDTO } from '@/modules/rescheduler-wk-history/dtos/add-rescheduler-wk-history.payload.dto';
import { ReschedulerWkHistoryResponse } from '@/modules/rescheduler-wk-history/dtos/rescheduler-wk-history-response.dto';
import { ReschedulerWkHistory } from '@/modules/rescheduler-wk-history/rescheduler-wk-history.entity';

@Injectable()
export class ReschedulerWkHistoryService {
  private readonly logger = new AppLogger(ReschedulerWkHistoryService.name);

  public constructor(
    @InjectRepository(ReschedulerWkHistory)
    private readonly reschedulerWkHistoryRepo: Repository<ReschedulerWkHistory>,
    private readonly pickingOrderService: PickingOrderService,
  ) {}

  public async getReschedulerWkHistoryById(
    reschedulerWkHistoryId: number,
    plant: number,
  ): Promise<ReschedulerWkHistoryResponse> {
    try {
      const reschedulerWkHistory = await this.reschedulerWkHistoryRepo.findOne({
        loadRelationIds: true,
        where: {
          plant,
          reschedulerWkHistoryId,
        },
      });

      if (!reschedulerWkHistory) {
        throw new NotFoundException('Rescheduler Wk History not Found');
      }
      return reschedulerWkHistory;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve Rescheduler Wk History by ID: ${error.message}`,
      );
      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve Rescheduler Wk History by id',
              error,
            );
      throw errorN;
    }
  }

  public async addReschedulerWkHistory(
    payload: AddReschedulerWkHistoryDTO,
  ): Promise<{ statusMessage: string; statusCode: number } | undefined> {
    try {
      const pickingOrder = await this.pickingOrderService.getOrderById(
        payload.pickingOrderId,
        payload.plant,
      );
      if (!pickingOrder) {
        this.logger.error('PickingOrder not found');
        return {
          statusCode: 404,
          statusMessage: 'PickingOrder not found',
        };
      }
      const pickOrderHasWkHistory =
        pickingOrder.reschedulerWkHistories.length > 0;
      if (!pickOrderHasWkHistory) {
        const reschedulerWkHistory = {
          ...payload,
          newPickingTime: payload.newPickingTime,
          oldPickingTime: payload.alertCreationTime,
          pickingOrder,
          reasonId: payload.reasonId,
        };
        await this.reschedulerWkHistoryRepo.save(reschedulerWkHistory);
        return {
          statusCode: 201,
          statusMessage: 'Inserted Rescheduler Wk history successfully',
        };
      }

      const reschedulerWkHistoryToFind =
        await this.reschedulerWkHistoryRepo.findOne({
          loadRelationIds: true,
          order: {
            createdAt: 'DESC',
          },
          where: {
            pickingOrderId: payload.pickingOrderId,
            plant: payload.plant,
          },
        });
      if (!reschedulerWkHistoryToFind) {
        this.logger.error('Rescheduler Work History not found');
        return {
          statusCode: 404,
          statusMessage: 'Rescheduler Work History not found',
        };
      }

      const reschedulerWkHistory = {
        ...payload,
        newPickingtime: payload.newPickingTime,
        oldPickingTime: reschedulerWkHistoryToFind.newPickingTime,
        pickingOrder,
        reasonId: payload.reasonId,
      };

      await this.reschedulerWkHistoryRepo.save(reschedulerWkHistory);

      return {
        statusCode: 201,
        statusMessage: 'Inserted Rescheduler Wk history successfully',
      };
    } catch (error) {
      this.logger.error('Failed to insert Rescheduler Wk History', error);
      return {
        statusCode: 500,
        statusMessage: 'Failed to insert Rescheduler Wk History',
      };
    }
  }

  public async addReschedulerWkHistoryInMass(
    plant: number,
    range: number,
    payload: Array<AddReschedulerWkHistoryInMassDTO>,
  ): Promise<Array<ReschedulerWkInMassResponse>> {
    try {
      const pickingOrderIds = payload.map((p) => p.pickingOrderId);

      const pickingOrders = await this.pickingOrderService.getOrderByIds(
        pickingOrderIds,
        plant,
      );

      const orderMap = new Map(
        pickingOrders.map((order) => [order.pickingOrderId, order]),
      );

      const historiesToSave: Array<ReschedulerWkHistory> = [];
      const results: Array<ReschedulerWkInMassResponse> = [];

      for (const orderPayload of payload) {
        const order = orderMap.get(orderPayload.pickingOrderId);
        if (order) {
          const oldTime = new Date(orderPayload.oldPickingTime);

          const newPickingTime = new Date(oldTime.getTime() + range);

          const history = new ReschedulerWkHistory();

          if (order.reschedulerWkHistories?.length > 0) {
            const lastHistory = await this.reschedulerWkHistoryRepo.findOne({
              where: { pickingOrderId: orderPayload.pickingOrderId, plant },
              order: { createdAt: 'DESC' },
            });
            if (lastHistory?.newPickingTime) {
              history.plant = plant;
              history.alertCreationTime = lastHistory.oldPickingTime;
              history.reasonId = orderPayload.reasonId;
              history.oldPickingTime = lastHistory.newPickingTime;
              history.newPickingTime = newPickingTime;
              history.pickingOrderId = orderPayload.pickingOrderId;
              history.comment = orderPayload.comment ?? null;
              results.push({
                pickingOrderId: orderPayload.pickingOrderId,
                newPickingTime: history.newPickingTime,
              });
            }
          } else {
            history.plant = plant;
            history.alertCreationTime = orderPayload.alertCreationTime;
            history.newPickingTime = newPickingTime;
            history.oldPickingTime = orderPayload.alertCreationTime;
            history.reasonId = orderPayload.reasonId;
            history.pickingOrderId = orderPayload.pickingOrderId;
            history.comment = orderPayload.comment ?? null;
            results.push({
              pickingOrderId: history.pickingOrderId,
              newPickingTime: history.newPickingTime,
            });
          }
          historiesToSave.push(history);
        } else {
          this.logger.warn(
            `pickingOrderId=${orderPayload.pickingOrderId} for plant=${plant}`,
          );
        }
      }
      // Save all histories after processing the entire payload
      if (historiesToSave.length > 0) {
        try {
          await this.reschedulerWkHistoryRepo.save(historiesToSave);
        } catch (error) {
          this.logger.error('Error saving histories:', error);
        }
      }

      return results;
      // Compute newPickingTime
    } catch (error) {
      this.logger.error('Failed to insert Rescheduler Wk History', error);
      return [];
    }
  }
}

